{
  "name": "app",
  "version": "1.0.0",
  "description": "Express app with AWS Secrets Manager integration",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "dev": "NODE_ENV=development node app.js",
    "test": "NODE_ENV=test node app.js"
  },
  "dependencies": {
    "@aws-sdk/client-secrets-manager": "^3.0.0",
    "dotenv": "^16.0.0",
    "express": "^4.18.0"
  }
}

'use strict';

/**
 * secrets.js
 *
 * Provides getSecret(name) with two resolution strategies:
 *
 *  1. PRODUCTION (NODE_ENV !== 'development' && NODE_ENV !== 'test'):
 *     Fetches the secret value from AWS Secrets Manager.  Each secret is
 *     expected to be stored as a JSON string whose top-level key matches
 *     `name`, OR as a plain-string secret whose Secrets Manager secret-name
 *     equals `name`.
 *
 *  2. LOCAL FALLBACK (NODE_ENV === 'development' | 'test'):
 *     Reads the value from .env.test via dotenv.  This keeps developer
 *     laptops and CI environments working without AWS credentials while
 *     the production path stays clean.
 *
 * Secret *names* are never hard-coded here; they are derived exclusively
 * from the keys that already exist in .env.test, so adding or removing a
 * secret only requires editing that one file.
 */

const path = require('path');
const fs   = require('fs');
const {
  SecretsManagerClient,
  GetSecretValueCommand,
} = require('@aws-sdk/client-secrets-manager');

// ─── 1. Parse .env.test to obtain the canonical list of secret names ─────────
//
// We use dotenv's `parse()` helper rather than `config()` so that we never
// inject anything into process.env automatically; callers must go through
// getSecret() instead.

const ENV_FILE = path.resolve(__dirname, '.env.test');

function loadEnvFile() {
  if (!fs.existsSync(ENV_FILE)) {
    throw new Error(`secrets.js: expected env file not found at ${ENV_FILE}`);
  }
  // dotenv.parse returns a plain object – no process.env mutation.
  const dotenv = require('dotenv');
  return dotenv.parse(fs.readFileSync(ENV_FILE));
}

// Parsed once at module load; re-used for the fallback path.
const envFileSecrets = loadEnvFile();

/**
 * The complete list of secret names recognised by this application.
 * Derived from .env.test keys – no values, no hard-coding.
 */
const REQUIRED_SECRET_NAMES = Object.freeze(Object.keys(envFileSecrets));

// ─── 2. AWS Secrets Manager client (lazy-initialised) ────────────────────────

let _smClient = null;

function getSecretsManagerClient() {
  if (!_smClient) {
    _smClient = new SecretsManagerClient({
      // Region can be overridden via AWS_REGION / AWS_DEFAULT_REGION env vars
      // or the standard AWS credential chain – no values are hard-coded here.
      region: process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION || 'us-east-1',
    });
  }
  return _smClient;
}

// ─── 3. In-process cache (per-process lifetime) ──────────────────────────────
//
// Secrets Manager is billed per API call, so we cache each resolved value
// for the lifetime of the process.  Restart the process to pick up rotated
// secrets (or remove the cache entry and call getSecret() again).

const _cache = new Map();

// ─── 4. Core fetch logic ─────────────────────────────────────────────────────

/**
 * Fetch a secret from AWS Secrets Manager.
 *
 * Convention:
 *   - If the stored secret string is valid JSON, the function tries to return
 *     `parsed[name]` first, then falls back to the full string value so that
 *     both "one secret per key" and "one JSON blob" storage layouts work.
 *   - If the stored secret string is not JSON, it is returned as-is.
 *
 * @param {string} name  The secret name (must be a key in .env.test).
 * @returns {Promise<string>}
 */
async function fetchFromSecretsManager(name) {
  const client  = getSecretsManagerClient();
  const command = new GetSecretValueCommand({ SecretId: name });

  let response;
  try {
    response = await client.send(command);
  } catch (err) {
    throw new Error(
      `secrets.js: failed to fetch secret "${name}" from AWS Secrets Manager – ${err.message}`
    );
  }

  const raw = response.SecretString;
  if (raw === undefined || raw === null) {
    throw new Error(
      `secrets.js: secret "${name}" has no SecretString (binary secrets are not supported)`
    );
  }

  // Try JSON layout first so a single JSON blob can hold many keys.
  try {
    const parsed = JSON.parse(raw);
    if (typeof parsed === 'object' && parsed !== null && name in parsed) {
      return String(parsed[name]);
    }
    // JSON blob exists but doesn't contain this key – return the whole string.
    return raw;
  } catch {
    // Not JSON – the entire string is the secret value.
    return raw;
  }
}

/**
 * Retrieve a secret value from .env.test (local / CI fallback).
 *
 * @param {string} name
 * @returns {string}
 */
function fetchFromEnvFile(name) {
  if (!(name in envFileSecrets)) {
    throw new Error(
      `secrets.js: "${name}" is not defined in ${ENV_FILE}. ` +
      `Available secrets: ${REQUIRED_SECRET_NAMES.join(', ')}`
    );
  }
  return envFileSecrets[name];
}

// ─── 5. Public API ────────────────────────────────────────────────────────────

const IS_LOCAL =
  process.env.NODE_ENV === 'development' || process.env.NODE_ENV === 'test';

/**
 * Get a secret by name.
 *
 * - In production: fetches from AWS Secrets Manager (cached after first call).
 * - In development / test: reads from .env.test via dotenv (no AWS needed).
 *
 * @param {string} name  Must match one of the keys in .env.test.
 * @returns {Promise<string>}
 */
async function getSecret(name) {
  if (!REQUIRED_SECRET_NAMES.includes(name)) {
    throw new Error(
      `secrets.js: unknown secret "${name}". ` +
      `Register it by adding it to ${ENV_FILE} first.`
    );
  }

  // Return cached value when available (production only; dev reads are cheap).
  if (!IS_LOCAL && _cache.has(name)) {
    return _cache.get(name);
  }

  const value = IS_LOCAL
    ? fetchFromEnvFile(name)
    : await fetchFromSecretsManager(name);

  if (!IS_LOCAL) {
    _cache.set(name, value);
  }

  return value;
}

// ─── 6. Exports ───────────────────────────────────────────────────────────────

module.exports = {
  /**
   * Ordered list of every secret name this application requires.
   * Derived from .env.test keys at module load time.
   */
  REQUIRED_SECRET_NAMES,

  /**
   * Fetch a single secret by name.
   * Resolves from AWS Secrets Manager in production,
   * falls back to .env.test in development/test.
   *
   * @param  {string}          name
   * @returns {Promise<string>}
   */
  getSecret,
};

'use strict';

/**
 * app.js
 *
 * All secret values are obtained through secrets.getSecret(name).
 * No values are read from process.env or hard-coded here.
 */

const express = require('express');
const { getSecret, REQUIRED_SECRET_NAMES } = require('./secrets');

const app = express();

// ─── Startup: verify every required secret is reachable ──────────────────────
//
// We resolve all secrets once at boot so that a misconfigured environment
// (missing IAM permissions, wrong secret name, etc.) fails fast with a clear
// error rather than surfacing later during a live request.

async function loadSecrets() {
  const results = await Promise.allSettled(
    REQUIRED_SECRET_NAMES.map((name) => getSecret(name))
  );

  const failures = results
    .map((r, i) => (r.status === 'rejected' ? REQUIRED_SECRET_NAMES[i] : null))
    .filter(Boolean);

  if (failures.length > 0) {
    throw new Error(
      `app.js: failed to load secret(s) at startup: ${failures.join(', ')}`
    );
  }

  // Return a convenience lookup so routes can call secrets.get('NAME')
  // without firing another async round-trip.
  const lookup = {};
  REQUIRED_SECRET_NAMES.forEach((name, i) => {
    lookup[name] = results[i].value;
  });
  return lookup;
}

// ─── Routes ──────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Example route that consumes a secret on demand.
// The value is fetched (or returned from cache) by the secrets module.
app.get('/db-status', async (req, res) => {
  try {
    const dbUrl = await getSecret('DATABASE_URL');
    // Use only the non-sensitive parts for the response.
    const { hostname, port, pathname } = new URL(dbUrl);
    res.json({ connected: true, host: hostname, port, db: pathname.slice(1) });
  } catch (err) {
    res.status(500).json({ connected: false, error: err.message });
  }
});

// ─── Boot ─────────────────────────────────────────────────────────────────────

async function start() {
  // Eagerly validate all secrets before accepting traffic.
  await loadSecrets();

  app.listen(3000, () => {
    console.log('Server running on port 3000');
  });
}

start().catch((err) => {
  console.error('Fatal startup error:', err.message);
  process.exit(1);
});

module.exports = app;

