const Module = require('module');
const orig   = Module._resolveFilename.bind(Module);
Module._resolveFilename = (req, ...rest) => {
  if (req === 'dotenv' || req === '@aws-sdk/client-secrets-manager') return req;
  return orig(req, ...rest);
};
