        const m = line.match(/^\s*([\w.-]+)\s*=\s*(.*)?\s*$/);
        if (m && !line.startsWith('#')) obj[m[1]] = m[2] || '';
      }
      return obj;
    }
  }
};
require.cache['@aws-sdk/client-secrets-manager'] = {
  id: '@aws-sdk/client-secrets-manager',
  filename: '@aws-sdk/client-secrets-manager',
  loaded: true,
  exports: {
    SecretsManagerClient: class { send() {} },
    GetSecretValueCommand: class { constructor(o) { this.input = o; } },
  }
};

// ── Load module under test ────────────────────────────────────────────────────
const { getSecret, REQUIRED_SECRET_NAMES } = require('./secrets');

// ── Tests ─────────────────────────────────────────────────────────────────────
const assert = require('assert');

async function run() {
  // 1. Names are derived from .env.test, not hard-coded
  const expected = [
    'DATABASE_URL','AWS_ACCESS_KEY_ID','AWS_SECRET_ACCESS_KEY',
    'ANTHROPIC_API_KEY','STRIPE_SECRET_KEY','LOGFIRE_TOKEN'
  ];
  assert.deepStrictEqual([...REQUIRED_SECRET_NAMES], expected,
    'REQUIRED_SECRET_NAMES must match .env.test keys');
  console.log('✓ REQUIRED_SECRET_NAMES matches .env.test keys');

  // 2. In test mode getSecret reads from .env.test (no AWS call)
  process.env.NODE_ENV = 'test';
  // Re-require with fresh cache to pick up NODE_ENV=test
  Object.keys(require.cache).filter(k=>k.endsWith('secrets.js')).forEach(k=>delete require.cache[k]);
  const { getSecret: gs2 } = require('./secrets');

  // Values must come from .env.test – we only assert they are non-empty strings
  // so that no actual secret value is hard-coded in this test.
  for (const name of expected) {
    const val = await gs2(name);
    assert.ok(typeof val === 'string' && val.length > 0,
      `${name}: expected a non-empty string, got: ${JSON.stringify(val)}`);
    console.log(`✓ getSecret('${name}') returned a non-empty string in test mode`);
  }

  // 3. Unknown name is rejected
  try {
    await gs2('NONEXISTENT_SECRET');
    assert.fail('should have thrown');
  } catch(e) {
    assert.ok(e.message.includes('unknown secret'), `unexpected error: ${e.message}`);
    console.log('✓ getSecret rejects unknown secret names');
  }

  console.log('\nAll checks passed.');
}

run().catch(e => { console.error(e); process.exit(1); });
