{
  "name": "app",
  "version": "1.0.0",
  "description": "Express app using AWS Secrets Manager for secret management",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "dev": "NODE_ENV=development node app.js"
  },
  "dependencies": {
    "@aws-sdk/client-secrets-manager": "^3.600.0",
    "dotenv": "^16.4.5",
    "express": "^4.19.2"
  }
}

/**
 * secrets.js
 *
 * Centralised secret-loading module.
 *
 * Strategy
 * --------
 * Production / staging  →  AWS Secrets Manager (primary, always attempted first).
 * Development fallback  →  .env.test loaded via dotenv, used ONLY when
 *                          NODE_ENV=development AND Secrets Manager is unreachable.
 *
 * What this module intentionally does NOT do
 * -------------------------------------------
 *  - It never logs, prints, or embeds secret values.
 *  - It never loads .env.test outside of NODE_ENV=development.
 *  - It never hard-codes any secret value.
 *
 * Required environment variables (supplied by the execution environment,
 * not by this module):
 *   AWS_REGION          – AWS region for Secrets Manager (e.g. "us-east-1")
 *   AWS_ACCESS_KEY_ID   – IAM credentials  (or use an IAM role / ECS task role)
 *   AWS_SECRET_ACCESS_KEY
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const {
  SecretsManagerClient,
  GetSecretValueCommand,
} = require('@aws-sdk/client-secrets-manager');

// ---------------------------------------------------------------------------
// 1.  Derive the list of required secret names from .env.test
//     We parse only the KEY names — never touching the values — so the
//     required-secrets list stays in sync with the .env.test file
//     automatically.
// ---------------------------------------------------------------------------

const ENV_FILE = path.resolve(__dirname, '.env.test');

/**
 * Parse an env file and return an array of key names, ignoring blank lines
 * and comment lines.  Values are intentionally discarded.
 *
 * @param {string} filePath  Absolute path to the env file.
 * @returns {string[]}       Ordered array of unique key names.
 */
function parseEnvKeys(filePath) {
  if (!fs.existsSync(filePath)) {
    return [];
  }

  const lines = fs.readFileSync(filePath, 'utf8').split('\n');
  const keys  = [];

  for (const raw of lines) {
    const line = raw.trim();

    // Skip blank lines and comment lines
    if (!line || line.startsWith('#')) {
      continue;
    }

    // Accept   KEY=...   or   KEY = ...   (any spacing around =)
    const eqIndex = line.indexOf('=');
    if (eqIndex < 1) {
      continue;
    }

    const key = line.slice(0, eqIndex).trim();
    if (key && !keys.includes(key)) {
      keys.push(key);
    }
  }

  return keys;
}

/** Ordered list of secret names this application requires. */
const REQUIRED_SECRET_NAMES = parseEnvKeys(ENV_FILE);

// ---------------------------------------------------------------------------
// 2.  AWS Secrets Manager client
//     AWS_REGION must be set in the execution environment.
// ---------------------------------------------------------------------------

const smClient = new SecretsManagerClient({
  region: process.env.AWS_REGION || 'us-east-1',
});

// ---------------------------------------------------------------------------
// 3.  In-process cache  (TTL = 5 minutes)
//     Avoids hammering Secrets Manager on every request while still
//     picking up rotations within a reasonable window.
// ---------------------------------------------------------------------------

const CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes

/** @type {Map<string, { value: string, fetchedAt: number }>} */
const cache = new Map();

/**
 * Return a cached value if it exists and has not expired.
 *
 * @param {string} name
 * @returns {string|null}
 */
function getCached(name) {
  const entry = cache.get(name);
  if (!entry) return null;
  if (Date.now() - entry.fetchedAt > CACHE_TTL_MS) {
    cache.delete(name);
    return null;
  }
  return entry.value;
}

/**
 * Store a value in the in-process cache.
 *
 * @param {string} name
 * @param {string} value
 */
function setCached(name, value) {
  cache.set(name, { value, fetchedAt: Date.now() });
}

// ---------------------------------------------------------------------------
// 4.  AWS Secrets Manager fetch
// ---------------------------------------------------------------------------

/**
 * Fetch a single secret value from AWS Secrets Manager.
 * Supports both plain-string secrets and JSON-encoded secrets.
 * When the secret is JSON, the key matching `name` is extracted.
 *
 * @param {string} name  The Secrets Manager secret name / ARN.
 * @returns {Promise<string>}
 * @throws  If the secret does not exist or the call fails.
 */
async function fetchFromSecretsManager(name) {
  const command = new GetSecretValueCommand({ SecretId: name });
  const response = await smClient.send(command);

  const raw = response.SecretString ?? null;
  if (raw === null) {
    throw new Error(
      `[secrets] Secret "${name}" returned a binary value, which is not supported.`
    );
  }

  // If the secret is a JSON blob, extract the matching key.
  // This supports the common pattern of storing all app secrets
  // in a single JSON secret in Secrets Manager.
  try {
    const parsed = JSON.parse(raw);
    if (typeof parsed === 'object' && parsed !== null && name in parsed) {
      return String(parsed[name]);
    }
    // JSON object but key not found — return the whole string so the
    // caller can decide what to do.
    return raw;
  } catch {
    // Not JSON — return the plain string value.
    return raw;
  }
}

// ---------------------------------------------------------------------------
// 5.  Development fallback via dotenv
//     Loaded lazily and only once; values are kept inside the dotenv
//     module's own parsed object, not re-exported from here.
// ---------------------------------------------------------------------------

let devEnvLoaded = false;

/**
 * Load .env.test into process.env exactly once, only in development mode.
 * Existing process.env values are never overwritten (dotenv default).
 */
function loadDevEnvOnce() {
  if (devEnvLoaded) return;
  devEnvLoaded = true;

  const dotenv = require('dotenv');
  const result = dotenv.config({ path: ENV_FILE });

  if (result.error) {
    console.warn(
      `[secrets] Warning: could not load ${ENV_FILE} for dev fallback:`,
      result.error.message
    );
  }
}

// ---------------------------------------------------------------------------
// 6.  Public API
// ---------------------------------------------------------------------------

/**
 * Retrieve the value for a named secret.
 *
 * Resolution order:
 *   1. In-process cache (if not expired).
 *   2. AWS Secrets Manager.
 *   3. process.env / .env.test  — ONLY when NODE_ENV=development and step 2
 *      fails.  A warning is printed so developers know they are not hitting
 *      Secrets Manager.
 *
 * @param {string} name  The secret name.  Must be one of REQUIRED_SECRET_NAMES
 *                       (though this is not strictly enforced to allow
 *                       one-off lookups).
 * @returns {Promise<string>}
 * @throws  {Error} If the secret cannot be resolved by any strategy.
 */
async function getSecret(name) {
  if (!name || typeof name !== 'string') {
    throw new TypeError('[secrets] getSecret() requires a non-empty string name.');
  }

  // 1 — cache
  const cached = getCached(name);
  if (cached !== null) {
    return cached;
  }

  // 2 — Secrets Manager
  try {
    const value = await fetchFromSecretsManager(name);
    setCached(name, value);
    return value;
  } catch (smError) {
    const isDev = process.env.NODE_ENV === 'development';

    if (!isDev) {
      // In production there is no safe fallback — surface the error clearly.
      throw new Error(
        `[secrets] Failed to retrieve secret "${name}" from AWS Secrets Manager: ${smError.message}`
      );
    }

    // 3 — dev fallback
    console.warn(
      `[secrets] AWS Secrets Manager unavailable in development; ` +
      `falling back to ${ENV_FILE} for secret "${name}". ` +
      `Error was: ${smError.message}`
    );

    loadDevEnvOnce();

    const devValue = process.env[name];
    if (devValue === undefined) {
      throw new Error(
        `[secrets] Secret "${name}" not found in ${ENV_FILE} either. ` +
        `Add it to .env.test for local development.`
      );
    }

    // Do NOT cache dev values — keep their lifetime to the current call so
    // that rotation during a dev session is picked up immediately.
    return devValue;
  }
}

/**
 * Pre-warm the cache by fetching all required secrets up-front.
 * Call this once during application startup to fail fast if any secret
 * is missing, rather than discovering the problem at request time.
 *
 * @returns {Promise<void>}
 * @throws  {AggregateError} listing every secret that could not be resolved.
 */
async function loadAllSecrets() {
  const errors = [];

  await Promise.all(
    REQUIRED_SECRET_NAMES.map(async (name) => {
      try {
        await getSecret(name);
      } catch (err) {
        errors.push(err);
      }
    })
  );

  if (errors.length > 0) {
    const messages = errors.map((e) => `  • ${e.message}`).join('\n');
    throw new AggregateError(
      errors,
      `[secrets] ${errors.length} secret(s) could not be loaded:\n${messages}`
    );
  }
}

module.exports = {
  /** Ordered list of secret names parsed from .env.test */
  REQUIRED_SECRET_NAMES,

  /**
   * Fetch a secret by name (Secrets Manager → dev fallback).
   * @type {(name: string) => Promise<string>}
   */
  getSecret,

  /**
   * Pre-warm all required secrets at startup.
   * @type {() => Promise<void>}
   */
  loadAllSecrets,
};

