const path = require('path');

// ---------------------------------------------------------------------------
// 1. Parse .env.test to discover the canonical list of required secret names.
//    Values from this file are ONLY used as a local fallback (see tier 2).
// ---------------------------------------------------------------------------

const ENV_FILE = path.resolve(__dirname, '.env.test');

