 * Minimal .env parser — supports `KEY=value` lines and `# comments`.
 * Returns { KEY: 'value', ... } without touching process.env.
 *
 * @param {string} filePath  Absolute path to the .env file.
 * @returns {Record<string, string>}
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return {};
  }

  const parsed = {};
  const lines  = fs.readFileSync(filePath, 'utf8').split('\n');

  for (const raw of lines) {
    const line = raw.trim();
    // Skip blanks and comments
    if (!line || line.startsWith('#')) continue;

    const eqIdx = line.indexOf('=');
    if (eqIdx === -1) continue;

    const key   = line.slice(0, eqIdx).trim();
    const value = line.slice(eqIdx + 1).trim();
    if (key) parsed[key] = value;
  }

  return parsed;
}

// Local fallback map — populated from .env.test (never written to process.env)
const localFallback = parseEnvFile(ENV_FILE);

/**
 * The authoritative list of secret names this application requires.
 * Derived solely from the keys in .env.test; no names are hardcoded.
 *
 * @type {string[]}
 */
const requiredSecrets = Object.keys(localFallback);

// ---------------------------------------------------------------------------
// 2. AWS Secrets Manager client — created lazily on first use.
// ---------------------------------------------------------------------------

let _smClient = null;

/**
 * Returns a (cached) SecretsManagerClient configured from the ambient
 * environment (AWS_REGION, AWS credentials, IAM role, etc.).
 *
 * @returns {import('@aws-sdk/client-secrets-manager').SecretsManagerClient}
 */
function getSmClient() {
  if (!_smClient) {
    // Require is intentionally deferred so the module can be imported in
    // environments where the AWS SDK is not installed (e.g. pure local dev
    // with no node_modules) without crashing at load time.
    const { SecretsManagerClient } = require('@aws-sdk/client-secrets-manager');
    _smClient = new SecretsManagerClient({
      region: process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION || 'us-east-1',
    });
