  return Boolean(
    process.env.AWS_ACCESS_KEY_ID ||
    process.env.AWS_PROFILE       ||
    process.env.AWS_CONTAINER_CREDENTIALS_RELATIVE_URI || // ECS task role
    process.env.AWS_WEB_IDENTITY_TOKEN_FILE              // EKS / IRSA
