  // Example: per-secret usage.  Secrets are accessed by the same names as the
  // keys in .env.test — no values are hardcoded anywhere in this file.
  // ---------------------------------------------------------------------------

  // Database connection (value fetched from cache after loadAllSecrets)
  const dbUrl    = await getSecret('DATABASE_URL');
  const stripeKey = await getSecret('STRIPE_SECRET_KEY');

  // In a real app you would pass these into your DB pool / SDK constructors:
