/**
 * secrets.js
 *
 * Centralised secret-loading module.
 *
 * Resolution order for every secret name:
 *   1. AWS Secrets Manager  (used when AWS_SECRETS_ENABLED=true, or when
 *      NODE_ENV is not "development" / "test")
 *   2. Local .env.test fallback  (used in development/test, or when
 *      Secrets Manager is explicitly disabled / unavailable)
 *
 * Secret names are derived exclusively from the *keys* present in .env.test —
 * no values from that file are ever forwarded to Secrets Manager or logged.
 *
 * Usage
 * -----
 *   const { getSecret, loadSecrets } = require('./secrets');
 *
 *   // Fetch a single secret (async)
 *   const dbUrl = await getSecret('DATABASE_URL');
 *
 *   // Pre-load all required secrets into a map (async, call once at startup)
 *   const secrets = await loadSecrets();
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// 1.  Parse .env.test to discover the *names* of required secrets.
//     Values are loaded into process.env only when the local fallback is
//     active; the value strings themselves are never sent anywhere else.
// ---------------------------------------------------------------------------
const ENV_FILE = path.resolve(__dirname, '.env.test');

/**
 * Returns the list of secret key names declared in .env.test.
 * Skips blank lines and comment lines (# …).
 *
 * @returns {string[]}
 */
function getRequiredSecretNames() {
  if (!fs.existsSync(ENV_FILE)) {
    return [];
  }

  return fs
    .readFileSync(ENV_FILE, 'utf8')
    .split('\n')
    .map((line) => line.trim())
    .filter((line) => line && !line.startsWith('#'))
    .map((line) => line.split('=')[0].trim())
    .filter(Boolean);
}

const REQUIRED_SECRET_NAMES = getRequiredSecretNames();

// ---------------------------------------------------------------------------
// 2.  Determine the active strategy.
//
//     • AWS_SECRETS_ENABLED=true  → always use Secrets Manager
//     • AWS_SECRETS_ENABLED=false → always use local fallback
//     • (default) development/test env → local fallback
//                 any other NODE_ENV   → Secrets Manager
// ---------------------------------------------------------------------------
function isSecretsManagerEnabled() {
  const explicit = process.env.AWS_SECRETS_ENABLED;
  if (explicit !== undefined) {
    return explicit.toLowerCase() === 'true';
  }
  const env = (process.env.NODE_ENV || 'development').toLowerCase();
  return env !== 'development' && env !== 'test';
}

// ---------------------------------------------------------------------------
// 3.  Local fallback — dotenv loads .env.test values into process.env.
//     This block only runs when Secrets Manager is NOT enabled.
// ---------------------------------------------------------------------------
let localEnvLoaded = false;

function ensureLocalEnvLoaded() {
  if (localEnvLoaded) return;

  // Lazy-require dotenv so the module can be imported in production
  // environments where dotenv may not be installed.
  try {
    // eslint-disable-next-line global-require
    const dotenv = require('dotenv');
    const result = dotenv.config({ path: ENV_FILE });
    if (result.error) {
      console.warn('[secrets] dotenv could not load .env.test:', result.error.message);
    } else {
      console.info('[secrets] Loaded local secrets from .env.test (development/test mode).');
    }
  } catch (err) {
    console.warn('[secrets] dotenv not available; set env vars manually:', err.message);
  }

  localEnvLoaded = true;
}

// ---------------------------------------------------------------------------
// 4.  AWS Secrets Manager helper.
//
//     AWS region / credentials are expected to come from the standard AWS
//     credential chain (env vars, ~/.aws/credentials, IAM role, etc.) —
//     never hardcoded here.
// ---------------------------------------------------------------------------
let smClient = null; // lazily initialised

function getSecretsManagerClient() {
  if (smClient) return smClient;

  // eslint-disable-next-line global-require
  const { SecretsManagerClient } = require('@aws-sdk/client-secrets-manager');
  smClient = new SecretsManagerClient({
    region: process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION || 'us-east-1',
  });
  return smClient;
}

/**
 * Fetch a single secret string from AWS Secrets Manager.
 *
 * The secret is looked up by `name`; if Secrets Manager stores a JSON
 * object under that name, the function returns the raw JSON string so
 * callers can parse it themselves.
 *
 * @param {string} name  The secret name (or ARN) in Secrets Manager.
 * @returns {Promise<string>}
 */
async function fetchFromSecretsManager(name) {
  const { GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
  const client = getSecretsManagerClient();

  const response = await client.send(new GetSecretValueCommand({ SecretId: name }));

  if (response.SecretString !== undefined) {
    return response.SecretString;
  }

  // Binary secrets are base64-encoded in SecretBinary
  if (response.SecretBinary) {
    return Buffer.from(response.SecretBinary).toString('utf8');
  }

  throw new Error(`[secrets] Secrets Manager returned no value for: ${name}`);
}

// ---------------------------------------------------------------------------
// 5.  In-process cache — avoids repeated API calls within a single process
//     lifetime.  Cache is intentionally NOT persisted to disk or logs.
// ---------------------------------------------------------------------------
const cache = new Map();

// ---------------------------------------------------------------------------
// 6.  Public API
// ---------------------------------------------------------------------------

/**
 * Retrieve the value of a named secret.
 *
 * Resolution order:
 *   1. In-process cache (fast path)
 *   2. AWS Secrets Manager  (when enabled)
 *   3. Local .env.test via process.env  (fallback)
 *
 * @param {string} name  Secret name exactly as declared in .env.test /
 *                       Secrets Manager.
 * @returns {Promise<string>}
 * @throws  {Error} if the secret cannot be resolved from any source.
 */
async function getSecret(name) {
  // Fast path: already cached
  if (cache.has(name)) {
    return cache.get(name);
  }

  let value;

  if (isSecretsManagerEnabled()) {
    // ── Primary: AWS Secrets Manager ───────────────────────────────────────
    try {
      value = await fetchFromSecretsManager(name);
      console.info(`[secrets] Resolved '${name}' from AWS Secrets Manager.`);
    } catch (smErr) {
      // Surface the AWS error but still attempt the local fallback so that
      // local integration-test runs against a real-ish environment are not
      // completely broken by missing IAM permissions.
      console.warn(
        `[secrets] Secrets Manager lookup failed for '${name}': ${smErr.message}` +
          ' — falling back to local .env.test.',
      );
      ensureLocalEnvLoaded();
      value = process.env[name];
    }
  } else {
    // ── Fallback: local .env.test (development / test) ─────────────────────
    ensureLocalEnvLoaded();
    value = process.env[name];
    if (value !== undefined) {
      console.info(`[secrets] Resolved '${name}' from local .env.test (development mode).`);
    }
  }

  if (value === undefined || value === null) {
    throw new Error(
      `[secrets] Secret '${name}' could not be resolved from any source. ` +
        'Check AWS Secrets Manager configuration or .env.test.',
    );
  }

  cache.set(name, value);
  return value;
}

/**
 * Pre-load every secret listed in .env.test and return them as a plain
 * object keyed by secret name.  Call this once during application startup
 * so that subsequent calls to getSecret() are served from cache.
 *
 * @returns {Promise<Record<string, string>>}
 */
async function loadSecrets() {
  const results = await Promise.allSettled(
    REQUIRED_SECRET_NAMES.map(async (name) => {
      const value = await getSecret(name);
      return [name, value];
    }),
  );

  const secrets = {};
  const failures = [];

  for (const result of results) {
    if (result.status === 'fulfilled') {
      const [name, value] = result.value;
      secrets[name] = value;
    } else {
      failures.push(result.reason.message);
    }
  }

  if (failures.length > 0) {
    throw new Error(
      `[secrets] Failed to load ${failures.length} secret(s):\n` +
        failures.map((m) => `  • ${m}`).join('\n'),
    );
  }

  return secrets;
}

/**
 * The list of secret names that this application requires, derived from the
 * keys in .env.test.  Export for introspection / testing.
 *
 * @type {string[]}
 */
module.exports = {
  REQUIRED_SECRET_NAMES,
  getSecret,
  loadSecrets,
};

/**
 * app.js
 *
 * Express application entry-point.
 * Secrets are loaded via secrets.js — never via direct dotenv calls here.
 */

'use strict';

const express = require('express');
const { loadSecrets, getSecret } = require('./secrets');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Example: route that uses a secret at request time (lazy, cached after first call)
app.get('/db-status', async (req, res) => {
  try {
    const dbUrl = await getSecret('DATABASE_URL');
    // Use dbUrl to initialise/ping the DB client — value never sent to client
    const { hostname } = new URL(dbUrl);
    res.json({ status: 'reachable', host: hostname });
  } catch (err) {
    console.error('[app] Could not retrieve DATABASE_URL:', err.message);
    res.status(503).json({ status: 'unavailable', error: err.message });
  }
});

// ---------------------------------------------------------------------------
// Startup — pre-load all secrets before accepting traffic
// ---------------------------------------------------------------------------
async function start() {
  try {
    // loadSecrets() resolves every name listed in .env.test and populates the
    // internal cache; individual getSecret() calls throughout the app will be
    // served instantly from that cache afterwards.
    await loadSecrets();
    console.info('[app] All secrets loaded successfully.');
  } catch (err) {
    console.error('[app] Secret loading failed — refusing to start:', err.message);
    process.exit(1);
  }

  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.info(`[app] Server running on port ${PORT}`);
  });
}

// Only call start() when this file is executed directly (not when required by tests)
if (require.main === module) {
  start();
}

module.exports = { app, start };

/**
 * secrets.test.js
 *
 * Tests for secrets.js using only Node's built-in assert module.
 * AWS Secrets Manager is stubbed — no real AWS credentials needed.
 *
 * Run:  node secrets.test.js
 */

'use strict';

const assert = require('assert/strict');
const path   = require('path');
const fs     = require('fs');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

let passed = 0;
let failed = 0;

async function test(description, fn) {
  try {
    await fn();
    console.log(`  ✓  ${description}`);
    passed++;
  } catch (err) {
    console.error(`  ✗  ${description}`);
    console.error(`     ${err.message}`);
    failed++;
  }
}

/** Reset all require-cache entries for secrets.js so each test gets a fresh module. */
function resetSecretsModule() {
  const secretsPath = require.resolve('./secrets');
  delete require.cache[secretsPath];

  // Also reset the @aws-sdk stub so we can swap it between tests
  const sdkPath = path.resolve(__dirname, 'node_modules/@aws-sdk/client-secrets-manager');
