}

// ---------------------------------------------------------------------------
// SDK stub — injected via node_modules shimming through require.cache
// ---------------------------------------------------------------------------

/**
 * Install a lightweight stub for @aws-sdk/client-secrets-manager.
 * `handler` receives { SecretId } and should return { SecretString } or throw.
 */
function stubSecretsManager(handler) {
  class SecretsManagerClient {
    async send(command) { return handler(command.input); }
  }
  class GetSecretValueCommand {
    constructor(input) { this.input = input; }
  }

  // Register under the path Node would normally resolve the real SDK to
  const fakePath = path.resolve(__dirname, 'node_modules/@aws-sdk/client-secrets-manager');
  require.cache[fakePath] = {
    id: fakePath,
    filename: fakePath,
    loaded: true,
    exports: { SecretsManagerClient, GetSecretValueCommand },
  };
}

/** Remove the SDK stub. */
function removeSecretsManagerStub() {
  const fakePath = path.resolve(__dirname, 'node_modules/@aws-sdk/client-secrets-manager');
  delete require.cache[fakePath];
}

// ---------------------------------------------------------------------------
// Test suites
// ---------------------------------------------------------------------------

console.log('\n── REQUIRED_SECRET_NAMES ──────────────────────────────────────');

await test('exports an array of secret names parsed from .env.test', () => {
  const { REQUIRED_SECRET_NAMES } = require('./secrets');
  assert.ok(Array.isArray(REQUIRED_SECRET_NAMES), 'should be an array');
  assert.ok(REQUIRED_SECRET_NAMES.length > 0, 'should not be empty');
