  const { REQUIRED_SECRET_NAMES } = require('./secrets');
  for (const name of REQUIRED_SECRET_NAMES) {
    assert.ok(!name.startsWith('#'), `'${name}' looks like a comment line`);
    assert.notEqual(name.trim(), '', 'empty string should not appear');
  }
