await test('does not expose any secret values', () => {
  // Parse the raw .env.test file to collect actual values
  const raw = fs.readFileSync(path.resolve(__dirname, '.env.test'), 'utf8');
  const values = raw
    .split('\n')
    .filter((l) => l.trim() && !l.trim().startsWith('#'))
