// ---------------------------------------------------------------------------
// 3.  Local fallback — parse .env.test and populate process.env.
//
//     We include a minimal built-in parser so the module works with zero
//     npm dependencies in development/CI.  If dotenv is installed it is
//     used instead (it handles edge-cases like quoted values and escaped
//     characters more robustly).
// ---------------------------------------------------------------------------
let localEnvLoaded = false;

/**
 * Minimal .env parser — handles the common `KEY=VALUE` format.
 * Strips inline comments, respects single- and double-quoted values,
 * and skips blank lines and full-line comments.
 * Only sets a key if it is not already present in process.env (same
 * semantics as dotenv's default behaviour).
 *
 * @param {string} filePath  Absolute path to the .env file.
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) return;

  const lines = fs.readFileSync(filePath, 'utf8').split('\n');

  for (const raw of lines) {
    const line = raw.trim();
    if (!line || line.startsWith('#')) continue;

    const eqIdx = line.indexOf('=');
    if (eqIdx === -1) continue;

    const key = line.slice(0, eqIdx).trim();
    if (!key) continue;

    let val = line.slice(eqIdx + 1).trim();

    // Strip inline comments that are not inside quotes
    // e.g.  KEY=value  # comment
    const inlineComment = val.search(/\s+#/);
    if (inlineComment !== -1 && !/^['"]/.test(val)) {
      val = val.slice(0, inlineComment).trim();
    }

    // Strip surrounding quotes (single or double)
    if (
      (val.startsWith('"') && val.endsWith('"')) ||
      (val.startsWith("'") && val.endsWith("'"))
    ) {
      val = val.slice(1, -1);
    }

    // Do not overwrite variables already set in the environment
    if (process.env[key] === undefined) {
      process.env[key] = val;
    }
  }
}

function ensureLocalEnvLoaded() {
  if (localEnvLoaded) return;

  // Prefer dotenv if available (better edge-case handling), otherwise fall
  // back to the built-in parser above — no hard dependency required.
  let usedDotenv = false;
  try {
    // eslint-disable-next-line global-require
    const dotenv = require('dotenv');
    const result = dotenv.config({ path: ENV_FILE, override: false });
    if (result.error) {
      console.warn('[secrets] dotenv could not load .env.test:', result.error.message);
    } else {
      usedDotenv = true;
    }
  } catch {
    // dotenv not installed — use the built-in parser
  }

  if (!usedDotenv) {
    parseEnvFile(ENV_FILE);
  }

  console.info('[secrets] Loaded local secrets from .env.test (development/test mode).');
  localEnvLoaded = true;
}

