 * .env.test — no values from that file are ever read or used by this
 * module at runtime; they remain in their authoritative store.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// ---------------------------------------------------------------------------
// 1. Parse .env.test for KEY NAMES only
//    We read the file once at module load so that the set of required secret
//    names is always in sync with the .env.test contract — without ever
//    importing the values themselves into application memory via this module.
// ---------------------------------------------------------------------------

const ENV_FILE = path.resolve(__dirname, '.env.test');

/**
 * Returns the ordered list of secret key names declared in .env.test.
 * Lines that are blank or start with '#' are ignored.
 * Only the portion of each line before the first '=' is taken — the value
 * side is deliberately discarded.
 *
 * @returns {string[]}
 */
function parseRequiredSecretNames() {
  if (!fs.existsSync(ENV_FILE)) {
    console.warn(`[secrets] ${ENV_FILE} not found — no required secret names loaded`);
    return [];
  }

  const lines = fs.readFileSync(ENV_FILE, 'utf8').split('\n');

  return lines.reduce((names, line) => {
    const trimmed = line.trim();
    // Skip blank lines and comments
    if (!trimmed || trimmed.startsWith('#')) return names;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) return names;          // malformed line — skip

    const key = trimmed.slice(0, eqIndex).trim();
    if (key) names.push(key);
    return names;
  }, []);
}

/** Immutable list of secret names this application requires. */
const REQUIRED_SECRET_NAMES = Object.freeze(parseRequiredSecretNames());

// ---------------------------------------------------------------------------
// 2. Environment detection
// ---------------------------------------------------------------------------

const NODE_ENV              = (process.env.NODE_ENV || 'production').toLowerCase();
const IS_LOCAL_ENV          = NODE_ENV === 'development' || NODE_ENV === 'test';
const LOCAL_FALLBACK_ACTIVE = IS_LOCAL_ENV &&
                              process.env.ALLOW_LOCAL_SECRET_FALLBACK === 'true';

// ---------------------------------------------------------------------------
// 3. Local fallback — load .env.test values into a private map
//    This block only runs when LOCAL_FALLBACK_ACTIVE is true, keeping
//    production code paths entirely free of dotenv and the local file.
// ---------------------------------------------------------------------------

let _localSecrets = null;  // populated lazily on first use

function loadLocalSecrets() {
  if (_localSecrets) return _localSecrets;  // already loaded

  // dotenv is only required in local environments; production images need
  // not have it installed.
  let dotenv;
  try {
    dotenv = require('dotenv');
  } catch {
    throw new Error(
      '[secrets] dotenv is not installed. ' +
      'Run `npm install dotenv` for local development.'
    );
  }

  const result = dotenv.config({ path: ENV_FILE });
  if (result.error) {
    throw new Error(`[secrets] Failed to load ${ENV_FILE}: ${result.error.message}`);
  }

  // Mirror parsed values into a private map and immediately remove them
  // from process.env so that the rest of the application must go through
  // getSecret() and cannot accidentally bypass the abstraction.
  _localSecrets = new Map();
  for (const [key, value] of Object.entries(result.parsed || {})) {
    _localSecrets.set(key, value);
    delete process.env[key];
  }

  console.info(
    `[secrets] Local fallback active — loaded ${_localSecrets.size} secret(s) from ${ENV_FILE}`
  );
  return _localSecrets;
}

// ---------------------------------------------------------------------------
// 4. AWS Secrets Manager client
//    Created lazily so that unit tests that stub getSecret() never attempt
//    a real AWS connection.
// ---------------------------------------------------------------------------

let _smClient = null;

function getSecretsManagerClient() {
  if (_smClient) return _smClient;

  const region = process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION;
  if (!region) {
    throw new Error(
      '[secrets] AWS_REGION (or AWS_DEFAULT_REGION) must be set to use Secrets Manager.'
    );
  }

  _smClient = new SecretsManagerClient({ region });
  return _smClient;
}

// ---------------------------------------------------------------------------
// 5. In-process cache — avoids redundant API calls within a single process
//    lifetime.  TTL is intentionally short (5 min) so rotated secrets are
//    picked up without a restart.
// ---------------------------------------------------------------------------

const CACHE_TTL_MS = 5 * 60 * 1000;  // 5 minutes
const _cache = new Map();             // name → { value, expiresAt }

// ---------------------------------------------------------------------------
// 6. Public API
// ---------------------------------------------------------------------------

/**
 * Fetches a secret value by name.
 *
 * Resolution order:
 *   1. In-process cache (TTL = 5 min)
 *   2. AWS Secrets Manager  (production / staging)
 *   3. Local .env.test values  (development / test, opt-in)
 *
 * @param {string} name  — the secret name, matching a key in .env.test
 * @returns {Promise<string>}
 * @throws  if the secret cannot be resolved in any tier
 */
async function getSecret(name) {
  if (!name || typeof name !== 'string') {
    throw new TypeError('[secrets] getSecret() requires a non-empty string name');
  }

  // --- 6a. Cache hit ---
  const cached = _cache.get(name);
  if (cached && cached.expiresAt > Date.now()) {
    return cached.value;
  }

  // --- 6b. AWS Secrets Manager ---
  if (!LOCAL_FALLBACK_ACTIVE) {
    const client  = getSecretsManagerClient();
    const command = new GetSecretValueCommand({ SecretId: name });

    let response;
    try {
      response = await client.send(command);
    } catch (err) {
      throw new Error(
        `[secrets] Failed to fetch secret "${name}" from Secrets Manager: ${err.message}`
      );
    }

    // Secrets Manager returns either SecretString or SecretBinary
    const value = response.SecretString
      ?? Buffer.from(response.SecretBinary, 'base64').toString('utf8');

    _cache.set(name, { value, expiresAt: Date.now() + CACHE_TTL_MS });
    return value;
  }

  // --- 6c. Local .env.test fallback ---
  const localMap = loadLocalSecrets();
  if (!localMap.has(name)) {
    throw new Error(
      `[secrets] Secret "${name}" not found in local fallback (${ENV_FILE}). ` +
      'Add it to .env.test for development use.'
    );
  }

  const value = localMap.get(name);
  // Cache local values with the same TTL for consistency
  _cache.set(name, { value, expiresAt: Date.now() + CACHE_TTL_MS });
  return value;
}

/**
 * Fetches all secrets listed in .env.test and returns them as a plain
 * object keyed by secret name.  Useful for bulk initialisation at startup.
 *
 * @returns {Promise<Record<string, string>>}
 */
async function getAllSecrets() {
  const entries = await Promise.all(
    REQUIRED_SECRET_NAMES.map(async (name) => [name, await getSecret(name)])
  );
  return Object.fromEntries(entries);
}

/**
 * Clears the in-process secret cache.  Intended for use in tests or after
 * a detected rotation event.
 */
function clearCache() {
  _cache.clear();
}

module.exports = {
  /** Ordered list of secret names derived from .env.test key names. */
  REQUIRED_SECRET_NAMES,
  getSecret,
  getAllSecrets,
  clearCache,
};

