/**
 * secrets.js
 *
 * Centralised secret-access module.
 *
 * Resolution order
 * ─────────────────
 * 1. AWS Secrets Manager  – used whenever NODE_ENV !== 'development' OR when
 *    the env var USE_AWS_SECRETS=true is set explicitly.
 * 2. Local .env.test file – fallback used only in development / test so that
 *    engineers can work without live AWS credentials.
 *
 * The module reads .env.test *only* to discover the canonical list of required
 * secret names (the keys).  Their values are never persisted in memory beyond
 * the scope of a single getSecret() call in the fallback path, and this file
 * never hard-codes any secret value.
 *
 * AWS Secrets Manager assumptions
 * ────────────────────────────────
 * • Each secret is stored as a single JSON object under one Secrets Manager
 *   entry whose name is controlled by the SECRETS_MANAGER_SECRET_ID env var
 *   (default: "app/secrets").
 * • The JSON object's keys match the names used in .env.test
 *   (DATABASE_URL, STRIPE_SECRET_KEY, …).
 * • The AWS region is read from AWS_REGION (default: "us-east-1").
 *
 * Usage
 * ──────
 *   const { getSecret, requiredSecretNames } = require('./secrets');
 *
 *   const dbUrl = await getSecret('DATABASE_URL');
 */

'use strict';

const path = require('path');
const fs   = require('fs');

const {
  SecretsManagerClient,
  GetSecretValueCommand,
} = require('@aws-sdk/client-secrets-manager');

// ─── Configuration (all values come from the environment, never hard-coded) ──

const ENV_FILE            = path.resolve(__dirname, '.env.test');
const SECRET_ID           = process.env.SECRETS_MANAGER_SECRET_ID || 'app/secrets';
const AWS_REGION          = process.env.AWS_REGION                 || 'us-east-1';
const IS_DEVELOPMENT      = process.env.NODE_ENV === 'development' || process.env.NODE_ENV === 'test';
const FORCE_AWS           = process.env.USE_AWS_SECRETS === 'true';
const USE_LOCAL_FALLBACK  = IS_DEVELOPMENT && !FORCE_AWS;

// ─── Parse .env.test to obtain the list of required secret names (keys only) ─

/**
 * Parses a .env file and returns an array of the variable *names* it declares.
 * Values are intentionally discarded here; they are only read later in
 * _loadLocalEnvMap() when the local fallback is actually needed.
 *
 * @param {string} filePath  Absolute path to the .env file.
 * @returns {string[]}       Ordered array of secret names, e.g. ['DATABASE_URL', …]
 */
function _parseEnvKeys(filePath) {
  if (!fs.existsSync(filePath)) {
    console.warn(`[secrets] Warning: env file not found at ${filePath}. No required names loaded.`);
    return [];
  }

  const lines = fs.readFileSync(filePath, 'utf8').split('\n');

  return lines.reduce((keys, line) => {
    // Strip inline comments and whitespace, skip blank lines and comment lines.
    const trimmed = line.replace(/#.*$/, '').trim();
    if (!trimmed) return keys;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex < 1) return keys;              // malformed or valueless line

    const key = trimmed.slice(0, eqIndex).trim();
    if (key) keys.push(key);
    return keys;
  }, []);
}

/**
 * Parses .env.test and returns a Map of name → value for local fallback use.
 * This function is called lazily and only in development/test mode.
 *
 * dotenv is used here so that quoting, escape sequences, and multi-line
 * values are all handled correctly.
 *
 * @returns {Map<string, string>}
 */
function _loadLocalEnvMap() {
  // dotenv.config() with a custom path returns { parsed: { KEY: VALUE, … } }
  // We read the parsed object directly rather than polluting process.env.
  const dotenv = require('dotenv');
  const result = dotenv.config({ path: ENV_FILE, override: false });

  if (result.error) {
    throw new Error(`[secrets] Failed to load local env file "${ENV_FILE}": ${result.error.message}`);
  }

  return new Map(Object.entries(result.parsed || {}));
}

// ─── AWS Secrets Manager client (created lazily to avoid cold-start cost) ────

let _smClient = null;

function _getSmClient() {
  if (!_smClient) {
    _smClient = new SecretsManagerClient({ region: AWS_REGION });
  }
  return _smClient;
}

// In-process cache: secret name → resolved value.
// Avoids redundant API calls within the same process lifetime.
const _cache = new Map();

// Tracks whether the full Secrets Manager payload has been fetched and cached.
let _smPayloadLoaded = false;

/**
 * Fetches the entire JSON secret from Secrets Manager once, then populates
 * _cache with every key it contains.  Subsequent calls for individual keys
 * are served from _cache without additional API round-trips.
 */
async function _loadSmPayload() {
  if (_smPayloadLoaded) return;

  const client  = _getSmClient();
  const command = new GetSecretValueCommand({ SecretId: SECRET_ID });

  let response;
  try {
    response = await client.send(command);
  } catch (err) {
    throw new Error(
      `[secrets] Could not retrieve secret "${SECRET_ID}" from AWS Secrets Manager ` +
      `(region: ${AWS_REGION}): ${err.message}`
    );
  }

  const raw = response.SecretString;
  if (!raw) {
    throw new Error(
      `[secrets] Secret "${SECRET_ID}" exists but has no SecretString value. ` +
      'Binary secrets are not supported.'
    );
  }

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch {
    throw new Error(
      `[secrets] Secret "${SECRET_ID}" is not valid JSON. ` +
      'Store secrets as a JSON object: { "KEY": "value", … }'
    );
  }

  if (typeof parsed !== 'object' || Array.isArray(parsed) || parsed === null) {
    throw new Error(
      `[secrets] Secret "${SECRET_ID}" must be a JSON object, not an array or primitive.`
    );
  }

  for (const [key, value] of Object.entries(parsed)) {
    _cache.set(key, String(value));
  }

  _smPayloadLoaded = true;
}

// ─── Public API ──────────────────────────────────────────────────────────────

/**
 * The ordered list of secret names declared in .env.test.
 * Use this to validate that all required secrets are present at startup.
 *
 * @type {string[]}
 */
const requiredSecretNames = _parseEnvKeys(ENV_FILE);

/**
 * Retrieves the value of a named secret.
 *
 * In production (or when USE_AWS_SECRETS=true) the value is fetched from
 * AWS Secrets Manager.  In development/test mode the value is read from the
 * local .env.test file via dotenv.
 *
 * Results are cached in memory for the lifetime of the process so that
 * repeated calls do not incur additional latency or API cost.
 *
 * @param  {string}          name  The secret name, e.g. 'DATABASE_URL'.
 * @returns {Promise<string>}      The secret value.
 * @throws  {Error}                If the secret cannot be found in either source.
 */
async function getSecret(name) {
  if (typeof name !== 'string' || !name.trim()) {
    throw new TypeError('[secrets] getSecret() requires a non-empty string name.');
  }

  // ── Local fallback path (development / test) ──────────────────────────────
  if (USE_LOCAL_FALLBACK) {
    if (_cache.has(name)) return _cache.get(name);

    const localMap = _loadLocalEnvMap();
    // Populate the cache from the full local map in one pass.
    for (const [k, v] of localMap) _cache.set(k, v);

    if (_cache.has(name)) return _cache.get(name);

    throw new Error(
      `[secrets] Secret "${name}" not found in local env file "${ENV_FILE}". ` +
      'Add it to .env.test for development.'
    );
  }

  // ── AWS Secrets Manager path (production / staging) ───────────────────────
  if (_cache.has(name)) return _cache.get(name);

  await _loadSmPayload();

  if (_cache.has(name)) return _cache.get(name);

  throw new Error(
    `[secrets] Secret "${name}" was not present in Secrets Manager entry "${SECRET_ID}". ` +
    `Available keys: ${[..._cache.keys()].join(', ') || '(none)'}`
  );
}

/**
 * Validates that every name in requiredSecretNames can be resolved.
 * Call this once at application startup to surface missing secrets early,
 * before any request is served.
 *
 * @returns {Promise<void>}
 * @throws  {Error}  Aggregated error listing every missing secret name.
 */
async function validateAllSecrets() {
  const errors = [];

  await Promise.all(
    requiredSecretNames.map(async (name) => {
      try {
        await getSecret(name);
      } catch (err) {
        errors.push(err.message);
      }
    })
  );

  if (errors.length > 0) {
    throw new Error(
      `[secrets] Startup validation failed — missing secrets:\n  • ${errors.join('\n  • ')}`
    );
  }
}

// ─── Cache management (primarily for testing) ────────────────────────────────

/**
 * Clears the in-process secret cache and resets the Secrets Manager payload
 * flag.  Useful in tests that need to simulate fresh process state.
 */
function _resetCache() {
  _cache.clear();
  _smPayloadLoaded = false;
}

module.exports = {
  getSecret,
  validateAllSecrets,
  requiredSecretNames,
  // Exported for unit tests only — not part of the public API.
  _resetCache,
};

'use strict';

const express = require('express');
const { getSecret, validateAllSecrets, requiredSecretNames } = require('./secrets');

const app = express();
app.use(express.json());

// ─── Startup: validate all required secrets before accepting traffic ──────────

async function initialise() {
  console.log(
    `[app] Validating ${requiredSecretNames.length} required secret(s): ` +
    requiredSecretNames.join(', ')
  );

  // Throws if any secret cannot be resolved — prevents the server from starting
  // in a misconfigured state.
  await validateAllSecrets();

  console.log('[app] All secrets resolved successfully.');
}

// ─── Routes ───────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

/**
 * Example route that consumes a secret at request time.
 *
 * getSecret() is safe to call per-request — values are cached in memory after
 * the first resolution so there is no repeated I/O cost.
 */
app.get('/db-status', async (req, res) => {
  try {
    const dbUrl = await getSecret('DATABASE_URL');

    // Use only the non-sensitive parts of the URL for the response.
    // Never return a raw secret value to a client.
    const { hostname, port, pathname } = new URL(dbUrl);
    res.json({
      connected: true,
      host: hostname,
      port: port || 5432,
      database: pathname.replace('/', ''),
    });
  } catch (err) {
    console.error('[app] /db-status error:', err.message);
    res.status(500).json({ error: 'Could not retrieve database configuration.' });
  }
});

// ─── Bootstrap ────────────────────────────────────────────────────────────────

// Only start listening when this file is run directly (not when it is
// require()'d by tests).
if (require.main === module) {
  initialise()
    .then(() => {
      const PORT = process.env.PORT || 3000;
      app.listen(PORT, () => {
        console.log(`[app] Server running on port ${PORT}`);
      });
    })
    .catch((err) => {
      console.error('[app] Fatal startup error:', err.message);
      process.exit(1);
    });
}

module.exports = app;

