/**
 * secrets.js
 *
 * Centralised secret-loading module.
 *
 * Production  – fetches each secret from AWS Secrets Manager by name.
 * Development – falls back to the local .env.test file when the env var
 *               NODE_ENV is not "production" AND Secrets Manager is
 *               unreachable (or returns an error).
 *
 * Rules this module intentionally enforces:
 *   • Secret *values* are never logged, never written to disk, and never
 *     embedded in any response object.
 *   • Only the *names* (keys) are read from .env.test at start-up to build
 *     the REQUIRED_SECRET_NAMES list; values stay in the file on disk.
 *   • Secrets Manager results are cached in-process for the lifetime of the
 *     process to avoid redundant network calls.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// 1.  Parse .env.test to discover the required secret *names* only.
//     Values are deliberately ignored here; they are only ever read inside
//     loadFromEnvFile() where they remain in-process and are never exposed.
// ---------------------------------------------------------------------------
const ENV_FILE = path.resolve(__dirname, '.env.test');

/**
 * Returns the list of secret names declared in .env.test.
 * Lines that are blank or start with '#' are skipped.
 * Only the portion before the first '=' is kept — the value is discarded.
 *
 * @returns {string[]}
 */
function parseSecretNames(filePath) {
  if (!fs.existsSync(filePath)) {
    return [];
  }

  return fs
    .readFileSync(filePath, 'utf8')
    .split('\n')
    .map((line) => line.trim())
    .filter((line) => line.length > 0 && !line.startsWith('#'))
    .map((line) => {
      const eqIndex = line.indexOf('=');
      // Discard everything after (and including) '='
      return eqIndex !== -1 ? line.slice(0, eqIndex).trim() : line.trim();
    })
    .filter(Boolean);
}

/** Immutable list of secret names this application requires. */
const REQUIRED_SECRET_NAMES = Object.freeze(parseSecretNames(ENV_FILE));

// ---------------------------------------------------------------------------
// 2.  AWS Secrets Manager client (lazy-initialised so that importing this
//     module in a non-AWS environment does not throw at require-time).
// ---------------------------------------------------------------------------

/** Lazily-created Secrets Manager client instance. */
let _smClient = null;

/**
 * Returns (and lazily creates) the AWS SecretsManagerClient.
 * Throws if the SDK package is not installed.
 *
 * @returns {import('@aws-sdk/client-secrets-manager').SecretsManagerClient}
 */
function getSmClient() {
  if (_smClient) return _smClient;

  // Require is deferred so that local-dev environments without the SDK
  // installed can still use the .env.test fallback path.
  const {
    SecretsManagerClient,
  } = require('@aws-sdk/client-secrets-manager'); // eslint-disable-line

  // The SDK automatically picks up AWS_REGION, AWS_ACCESS_KEY_ID,
  // AWS_SECRET_ACCESS_KEY, or instance-profile credentials — we never
  // hardcode them here.
  const region = process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION;
  if (!region) {
    throw new Error(
      'AWS region is not configured. Set the AWS_REGION environment variable.'
    );
  }

  _smClient = new SecretsManagerClient({ region });
  return _smClient;
}

// ---------------------------------------------------------------------------
// 3.  In-process cache  (name → value, populated lazily per secret)
// ---------------------------------------------------------------------------
const _cache = new Map();

// ---------------------------------------------------------------------------
// 4.  Local .env.test fallback loader
//     Reads the file fresh each call so hot-reloading works in development.
//     The parsed key→value map is kept only in this function's local scope
//     and is never exported.
// ---------------------------------------------------------------------------

/**
 * Parses .env.test and returns the value for `name`, or undefined.
 * The full key→value map is intentionally local; it is never exported or
 * attached to any wider-scoped object.
 *
 * @param {string} name
 * @returns {string|undefined}
 */
function loadFromEnvFile(name) {
  if (!fs.existsSync(ENV_FILE)) return undefined;

  const lines = fs.readFileSync(ENV_FILE, 'utf8').split('\n');

  for (const rawLine of lines) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;

    const eqIndex = line.indexOf('=');
    if (eqIndex === -1) continue;

    const key = line.slice(0, eqIndex).trim();
    if (key === name) {
      // Return value as-is (strip optional surrounding quotes)
      const raw = line.slice(eqIndex + 1).trim();
      return raw.replace(/^['"]|['"]$/g, '');
    }
  }

  return undefined;
}

// ---------------------------------------------------------------------------
// 5.  Core public API
// ---------------------------------------------------------------------------

/**
 * Fetches the secret value for `name`.
 *
 * Resolution order:
 *   1. In-process cache (populated after the first successful fetch).
 *   2. AWS Secrets Manager  (always attempted in production).
 *   3. Local .env.test fallback (non-production only, or when Secrets
 *      Manager is unreachable in development).
 *
 * @param {string} name  The secret name exactly as stored in Secrets Manager
 *                       (and as the key in .env.test).
 * @returns {Promise<string>} Resolves with the secret value.
 * @throws  {Error}           If the secret cannot be found by any means.
 */
async function getSecret(name) {
  if (!name || typeof name !== 'string') {
    throw new TypeError('getSecret: "name" must be a non-empty string.');
  }

  // --- cache hit ---
  if (_cache.has(name)) {
    return _cache.get(name);
  }

  const isProduction = process.env.NODE_ENV === 'production';

  // --- AWS Secrets Manager ---
  let smError = null;
  try {
    const {
      GetSecretValueCommand,
    } = require('@aws-sdk/client-secrets-manager'); // eslint-disable-line

    const client   = getSmClient();
    const command  = new GetSecretValueCommand({ SecretId: name });
    const response = await client.send(command);

    // Secrets Manager returns either SecretString or SecretBinary.
    const value =
      response.SecretString !== undefined
        ? response.SecretString
        : Buffer.from(response.SecretBinary, 'base64').toString('utf8');

    _cache.set(name, value);
    return value;
  } catch (err) {
    smError = err;

    if (isProduction) {
      // In production we never fall back to a file — surface the error.
      throw new Error(
        `[secrets] Failed to fetch "${name}" from Secrets Manager: ${err.message}`
      );
    }

    // Non-production: log a warning and attempt the local fallback.
    console.warn(
      `[secrets] Secrets Manager unavailable for "${name}" — ` +
        `falling back to ${path.basename(ENV_FILE)}. ` +
        `Reason: ${err.message}`
    );
  }

  // --- local .env.test fallback (development only) ---
  const localValue = loadFromEnvFile(name);

  if (localValue !== undefined) {
    _cache.set(name, localValue);
    return localValue;
  }

  // Nothing worked.
  const detail = smError ? ` (Secrets Manager error: ${smError.message})` : '';
  throw new Error(
    `[secrets] Secret "${name}" not found in Secrets Manager or ${path.basename(ENV_FILE)}.${detail}`
  );
}

/**
 * Pre-warms the cache by fetching all required secrets in parallel.
 * Call this once during application start-up so that the first real request
 * is never delayed by a cold-fetch.
 *
 * @returns {Promise<void>}
 * @throws  {Error} If any required secret cannot be resolved.
 */
async function loadAllSecrets() {
  if (REQUIRED_SECRET_NAMES.length === 0) {
    console.warn('[secrets] No secret names found in', path.basename(ENV_FILE));
    return;
  }

  const results = await Promise.allSettled(
    REQUIRED_SECRET_NAMES.map((name) => getSecret(name))
  );

  const failures = results
    .map((r, i) => (r.status === 'rejected' ? REQUIRED_SECRET_NAMES[i] : null))
    .filter(Boolean);

  if (failures.length > 0) {
    throw new Error(
      `[secrets] Failed to load required secret(s): ${failures.join(', ')}`
    );
  }

  console.log(
    `[secrets] Successfully loaded ${REQUIRED_SECRET_NAMES.length} secret(s).`
  );
}

/**
 * Clears the in-process cache.
 * Useful in tests to force re-fetching between test cases.
 */
function clearCache() {
  _cache.clear();
}

// ---------------------------------------------------------------------------
// 6.  Exports
// ---------------------------------------------------------------------------
module.exports = {
  /** Immutable list of secret names derived from .env.test key names. */
  REQUIRED_SECRET_NAMES,

  /** Fetch a single secret by name (with caching + dev fallback). */
  getSecret,

  /** Pre-warm cache for all required secrets at start-up. */
  loadAllSecrets,

  /** Clear in-process secret cache (test helper). */
  clearCache,
};

