 * Starts the HTTP server.
 * All required secrets are resolved (and cached) before the first request
 * can be handled, so route handlers can call getSecret() synchronously from
 * the cache without awaiting a network round-trip.
 */
async function startServer() {
  // Fetch (and cache) every secret declared in .env.test.
  // In production this calls AWS Secrets Manager; in development it falls
  // back to the local .env.test file if Secrets Manager is unreachable.
  await loadAllSecrets();

  // -------------------------------------------------------------------
  // Routes
  // -------------------------------------------------------------------

  app.get('/health', (req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  });

  app.get('/users', (req, res) => {
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  });

  // Example: a route that consumes a secret at request time.
  // getSecret() returns instantly from the warm cache populated above.
  app.get('/db-status', async (req, res) => {
    try {
      const dbUrl = await getSecret('DATABASE_URL');

      // Use only the *non-sensitive* parts of the URL for the status response.
      // Never echo the full connection string (it contains credentials).
      let host = 'unknown';
      try {
        host = new URL(dbUrl).hostname;
      } catch {
        // If parsing fails, leave host as 'unknown'.
      }

      res.json({ status: 'ok', host });
    } catch (err) {
      console.error('[/db-status] Could not retrieve DATABASE_URL:', err.message);
      res.status(503).json({ status: 'error', message: 'Database configuration unavailable.' });
    }
  });

  // -------------------------------------------------------------------
  // Start listening
  // -------------------------------------------------------------------
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

startServer().catch((err) => {
  console.error('[startup] Fatal error during secret loading:', err.message);
  process.exit(1);
});

module.exports = app;

