/**
 * secrets.js
 *
 * Provides getSecret(name) for the rest of the application.
 *
 * Resolution order
 * ────────────────
 * 1. AWS Secrets Manager  – always attempted first in production
 *    (NODE_ENV !== 'development').
 * 2. Local .env.test fallback – used when:
 *      • NODE_ENV === 'development', OR
 *      • the Secrets Manager call fails (e.g. no IAM role in CI).
 *
 * The set of *required* secret names is derived exclusively from the
 * keys present in .env.test so that no secret names are hardcoded here.
 *
 * Each secret is fetched individually so that fine-grained IAM policies
 * (one policy per secret ARN) are respected.  Results are cached in-
 * process to avoid redundant API calls within a single process lifetime.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// ── Configuration ────────────────────────────────────────────────────────────

const ENV_FILE      = path.resolve(__dirname, '.env.test');
const IS_PRODUCTION = process.env.NODE_ENV !== 'development';

// AWS region: prefer an explicit env var, fall back to us-east-1.
// This is the only value that is "configured" rather than "secret".
const AWS_REGION = process.env.AWS_REGION || 'us-east-1';

// ── Parse .env.test for secret names and local fallback values ───────────────

/**
 * Parses a .env file and returns { key: value } pairs.
 * Lines beginning with '#' and blank lines are ignored.
 * Values may optionally be quoted.
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {{ [key: string]: string }}
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return {};
  }

  const contents = fs.readFileSync(filePath, 'utf8');
  const result   = {};

  for (const rawLine of contents.split('\n')) {
    const line = rawLine.trim();

    // Skip blank lines and comments
    if (!line || line.startsWith('#')) continue;

    const eqIndex = line.indexOf('=');
    if (eqIndex === -1) continue;

    const key   = line.slice(0, eqIndex).trim();
    let   value = line.slice(eqIndex + 1).trim();

    // Strip optional surrounding quotes (single or double)
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    if (key) result[key] = value;
  }

  return result;
}

// Populated once at module load; never exported so values stay local.
const localFallback = parseEnvFile(ENV_FILE);

/**
 * The list of secret names the application requires, derived solely from
 * the keys in .env.test.  Exported so callers can validate at start-up
 * that every required secret is resolvable.
 *
 * @type {string[]}
 */
const REQUIRED_SECRET_NAMES = Object.keys(localFallback);

// ── AWS Secrets Manager client (lazy-initialised) ────────────────────────────

/** @type {SecretsManagerClient | null} */
let smClient = null;

function getSmClient() {
  if (!smClient) {
    smClient = new SecretsManagerClient({ region: AWS_REGION });
  }
  return smClient;
}

// ── In-process cache ─────────────────────────────────────────────────────────

/** @type {Map<string, string>} */
const secretCache = new Map();

// ── Core fetch logic ─────────────────────────────────────────────────────────

/**
 * Fetches a single secret from AWS Secrets Manager by name/ARN.
 *
 * @param {string} name - The Secrets Manager secret name or full ARN.
 * @returns {Promise<string>} The secret string value.
 * @throws If the secret does not exist or the caller lacks permission.
 */
async function fetchFromSecretsManager(name) {
  const command  = new GetSecretValueCommand({ SecretId: name });
  const response = await getSmClient().send(command);

  // Secrets Manager stores secrets as either a string or binary blob.
  if (response.SecretString !== undefined) {
    return response.SecretString;
  }

  // Binary secret: decode the base-64 Buffer
  if (response.SecretBinary) {
    return Buffer.from(response.SecretBinary).toString('utf8');
  }

  throw new Error(`Secret "${name}" returned neither SecretString nor SecretBinary.`);
}

/**
 * Returns the value for a named secret.
 *
 * In production the value is fetched from AWS Secrets Manager and the
 * result is cached for the lifetime of the process.  If Secrets Manager
 * is unreachable (e.g. running locally without credentials) and
 * NODE_ENV is 'development', the local .env.test value is returned
 * instead.  Outside of development the fallback is not used and the
 * error is re-thrown so that misconfigured deployments fail loudly.
 *
 * @param {string} name - Secret name as it appears in Secrets Manager
 *                        (and as the key in .env.test).
 * @returns {Promise<string>} Resolved secret value.
 */
async function getSecret(name) {
  // Return cached value if we already resolved this secret
  if (secretCache.has(name)) {
    return secretCache.get(name);
  }

  // ── Development shortcut ──────────────────────────────────────────────────
  // Skip the remote call entirely to keep local dev fast and offline-capable.
  if (!IS_PRODUCTION) {
    const localValue = localFallback[name];
    if (localValue !== undefined) {
      secretCache.set(name, localValue);
      return localValue;
    }
    throw new Error(
      `Secret "${name}" not found in local fallback (${ENV_FILE}). ` +
      'Add it to .env.test for local development.'
    );
  }

  // ── Production: AWS Secrets Manager ──────────────────────────────────────
  try {
    const value = await fetchFromSecretsManager(name);
    secretCache.set(name, value);
    return value;
  } catch (err) {
    // Surface the AWS error with context so it is easy to diagnose.
    throw new Error(
      `Failed to retrieve secret "${name}" from AWS Secrets Manager ` +
      `(region: ${AWS_REGION}): ${err.message}`
    );
  }
}

// ── Pre-flight validation ─────────────────────────────────────────────────────

/**
 * Eagerly resolves all required secrets and throws an AggregateError if
 * any are missing.  Call this once during application start-up so that
 * the process exits before binding to a port rather than crashing later
 * on the first real request.
 *
 * @returns {Promise<void>}
 */
async function validateAllSecrets() {
  const errors = [];

  await Promise.all(
    REQUIRED_SECRET_NAMES.map(async (name) => {
      try {
        await getSecret(name);
      } catch (err) {
        errors.push(err);
      }
    })
  );

  if (errors.length > 0) {
    const messages = errors.map((e) => `  • ${e.message}`).join('\n');
    throw new AggregateError(
      errors,
      `Application start-up failed: could not resolve ${errors.length} secret(s):\n${messages}`
    );
  }
}

// ── Exports ───────────────────────────────────────────────────────────────────

module.exports = {
  /** Async getter — resolves a secret by name. */
  getSecret,

  /**
   * Eagerly validate every required secret at start-up.
   * Throws AggregateError if any secret cannot be resolved.
   */
  validateAllSecrets,

  /**
   * The authoritative list of secret names required by this application,
   * derived from the keys present in .env.test.
   */
  REQUIRED_SECRET_NAMES,
};

/**
 * app.js
 *
 * Entry point for the Express application.
 *
 * Secrets are never loaded from the environment directly.  All secret
 * access goes through secrets.js, which fetches from AWS Secrets Manager
 * in production and falls back to the local .env.test file in development.
 */

'use strict';

const express  = require('express');
const { getSecret, validateAllSecrets, REQUIRED_SECRET_NAMES } = require('./secrets');

const app  = express();
const PORT = process.env.PORT || 3000;

// ── Middleware ────────────────────────────────────────────────────────────────

app.use(express.json());

// ── Routes ────────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

/**
 * Example of a route that needs a secret at request time.
 *
 * getSecret() is async and cached after the first call, so subsequent
 * requests pay no extra latency.  In a real app you would use the
 * resolved value to initialise a DB client, sign a request, etc.
 */
app.get('/db-status', async (req, res, next) => {
  try {
    // Fetch only what this route needs — no secret value is logged or sent
    // to the client.
    const dbUrl = await getSecret('DATABASE_URL');

    // Use the secret safely (e.g. open a connection).  Here we only
    // expose a non-sensitive summary to the caller.
    const redacted = dbUrl.replace(/:\/\/[^@]+@/, '://<credentials>@');
    res.json({ connected: true, endpoint: redacted });
  } catch (err) {
    next(err);
  }
});

// ── Error handler ─────────────────────────────────────────────────────────────

// eslint-disable-next-line no-unused-vars
app.use((err, req, res, _next) => {
  console.error('[app] Unhandled error:', err.message);
  res.status(500).json({ error: 'Internal server error' });
});

// ── Start-up ──────────────────────────────────────────────────────────────────

/**
 * Validate that every secret listed in .env.test can be resolved before
 * the server starts accepting traffic.  This converts a runtime secret-
 * fetch failure into a fast, clear start-up failure.
 */
async function start() {
  console.log(
    `[app] Resolving ${REQUIRED_SECRET_NAMES.length} required secret(s): ` +
    REQUIRED_SECRET_NAMES.join(', ')
  );

  await validateAllSecrets();

  console.log('[app] All secrets resolved successfully.');

  app.listen(PORT, () => {
    console.log(`[app] Server running on port ${PORT} (NODE_ENV=${process.env.NODE_ENV ?? 'unset'})`);
  });
}

start().catch((err) => {
  console.error('[app] Fatal start-up error:\n', err.message);
  process.exit(1);
});

module.exports = app;

