/**
 * secrets.js
 *
 * Centralised secret-access module.
 *
 * Resolution order
 * ────────────────
 * 1. AWS Secrets Manager  – always attempted first in every environment.
 * 2. .env.test fallback   – used only when the Secrets Manager call fails AND
 *                           NODE_ENV is NOT "production".  This lets developers
 *                           run the app locally without AWS credentials while
 *                           keeping production safe.
 *
 * The module reads .env.test once at start-up to discover the canonical list
 * of secret *names* (keys).  The values in that file are only ever used as the
 * local fallback; they are never forwarded to Secrets Manager or logged.
 *
 * Usage
 * ─────
 *   const { getSecret, REQUIRED_SECRETS } = require('./secrets');
 *
 *   const dbUrl = await getSecret('DATABASE_URL');
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// ─── Configuration ────────────────────────────────────────────────────────────

const ENV_FILE        = path.resolve(__dirname, '.env.test');
const IS_PRODUCTION   = process.env.NODE_ENV === 'production';
const AWS_REGION      = process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION || 'us-east-1';

// ─── Parse .env.test to extract secret names and local fallback values ────────

/**
 * Parses a .env-style file and returns a Map of key → value.
 * Lines beginning with '#' and blank lines are ignored.
 * Values are NOT loaded into process.env — they stay private inside this module.
 *
 * @param {string} filePath - Absolute path to the env file.
 * @returns {Map<string, string>}
 */
function parseEnvFile(filePath) {
  const entries = new Map();

  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      // File is optional in CI / production images — nothing to fall back to.
      return entries;
    }
    throw err;
  }

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;          // blank / comment

    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) continue;                                  // malformed line

    const key   = trimmed.slice(0, eqIdx).trim();
    const value = trimmed.slice(eqIdx + 1).trim();

    if (key) entries.set(key, value);
  }

  return entries;
}

// Build the canonical secret map from .env.test once at module load time.
const _localSecretMap = parseEnvFile(ENV_FILE);

/**
 * The list of secret names declared in .env.test.
 * Consumers can use this to pre-warm the cache or validate configuration at
 * start-up without needing to know the actual key names.
 *
 * @type {string[]}
 */
const REQUIRED_SECRETS = [..._localSecretMap.keys()];

// ─── AWS Secrets Manager client (lazy singleton) ──────────────────────────────

let _smClient = null;

/**
 * Returns a lazily-created SecretsManagerClient.
 * Creating it lazily means unit tests that never call getSecret() do not need
 * AWS credentials at all.
 *
 * @returns {SecretsManagerClient}
 */
function _getSmClient() {
  if (!_smClient) {
    _smClient = new SecretsManagerClient({ region: AWS_REGION });
  }
  return _smClient;
}

// ─── In-process cache ─────────────────────────────────────────────────────────

// Avoid hammering Secrets Manager with identical calls in the same process.
const _cache = new Map(); // name → resolved string value

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Fetches a secret value by name.
 *
 * Tries AWS Secrets Manager first.  Falls back to the .env.test value when:
 *   - the Secrets Manager call fails (e.g. no credentials, secret not found),
 *     AND
 *   - NODE_ENV is not "production".
 *
 * Throws if the secret cannot be resolved by any means.
 *
 * Results are cached in-process for the lifetime of the Node.js process, so
 * repeat calls are cheap.
 *
 * @param {string} name - The secret name / key (e.g. "DATABASE_URL").
 * @returns {Promise<string>} The plaintext secret value.
 */
async function getSecret(name) {
  if (!name || typeof name !== 'string') {
    throw new TypeError(`getSecret: 'name' must be a non-empty string (got ${JSON.stringify(name)})`);
  }

  // Return from cache if already resolved.
  if (_cache.has(name)) {
    return _cache.get(name);
  }

  // ── 1. Try AWS Secrets Manager ────────────────────────────────────────────
  let smValue;
  try {
    smValue = await _fetchFromSecretsManager(name);
  } catch (smErr) {
    if (IS_PRODUCTION) {
      // In production there is no safe fallback — surface the original error.
      throw new Error(
        `[secrets] Failed to retrieve secret "${name}" from AWS Secrets Manager ` +
        `(NODE_ENV=production; local fallback is disabled): ${smErr.message}`
      );
    }

    // ── 2. Fall back to .env.test (non-production only) ───────────────────
    console.warn(
      `[secrets] AWS Secrets Manager unavailable for "${name}" ` +
      `(${smErr.message}). Falling back to .env.test (development mode).`
    );

    if (!_localSecretMap.has(name)) {
      throw new Error(
        `[secrets] Secret "${name}" not found in AWS Secrets Manager ` +
        `and has no entry in .env.test. ` +
        `Available local keys: [${[..._localSecretMap.keys()].join(', ')}]`
      );
    }

    smValue = _localSecretMap.get(name);
  }

  _cache.set(name, smValue);
  return smValue;
}

/**
 * Fetches a single secret from AWS Secrets Manager.
 * Handles both string secrets and JSON-blob secrets (returning the raw JSON
 * string so callers can parse further if needed).
 *
 * @param {string} name
 * @returns {Promise<string>}
 * @throws if the API call fails for any reason.
 */
async function _fetchFromSecretsManager(name) {
  const client  = _getSmClient();
  const command = new GetSecretValueCommand({ SecretId: name });
  const response = await client.send(command);

  if (typeof response.SecretString === 'string') {
    return response.SecretString;
  }

  if (response.SecretBinary) {
    // SecretBinary is a Uint8Array; decode it as UTF-8.
    return Buffer.from(response.SecretBinary).toString('utf8');
  }

  throw new Error(`[secrets] Secret "${name}" returned neither SecretString nor SecretBinary.`);
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = { getSecret, REQUIRED_SECRETS };

'use strict';

/**
 * app.js
 *
 * All secrets are fetched at start-up via secrets.js, which tries AWS Secrets
 * Manager first and falls back to .env.test in non-production environments.
 * No secret values are hard-coded here.
 */

const express             = require('express');
const { getSecret, REQUIRED_SECRETS } = require('./secrets');

const app = express();

// ─── Initialise secrets then start the server ─────────────────────────────────

async function initAndStart() {

  // Eagerly resolve every secret declared in .env.test so the process fails
  // fast at start-up if anything is missing, rather than crashing mid-request.
  console.log(`[app] Resolving ${REQUIRED_SECRETS.length} secret(s): ${REQUIRED_SECRETS.join(', ')}`);

  let secrets;
  try {
    secrets = Object.fromEntries(
      await Promise.all(
        REQUIRED_SECRETS.map(async (name) => [name, await getSecret(name)])
      )
    );
  } catch (err) {
    console.error('[app] Fatal: could not resolve required secrets at start-up.', err.message);
    process.exit(1);
  }

  console.log(`[app] All secrets resolved successfully.`);

  // ── Routes ──────────────────────────────────────────────────────────────────

  app.get('/health', (req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  });

  app.get('/users', (req, res) => {
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ]);
  });

  // Example: a route that uses a secret at request-time via getSecret().
  // getSecret() caches the value in-process, so this is not an extra API call.
  app.get('/db-info', async (req, res, next) => {
    try {
      const dbUrl = await getSecret('DATABASE_URL');
      // Expose only non-sensitive metadata (never the raw secret value).
      const url   = new URL(dbUrl);
      res.json({ host: url.hostname, database: url.pathname.slice(1) });
    } catch (err) {
      next(err);
    }
  });

  // ── Start listening ──────────────────────────────────────────────────────────

  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`[app] Server running on port ${PORT}`);
  });
}

initAndStart();

module.exports = app;

