 *
 * Resolution order
 * ─────────────────
 * 1. AWS Secrets Manager  (always attempted first in non-dev environments)
 * 2. .env.test fallback   (used when NODE_ENV=development OR when Secrets
 *                          Manager is unavailable and ALLOW_LOCAL_FALLBACK=true)
 *
 * The module reads the list of *required* secret names directly from the keys
 * found in .env.test so that no secret name — and certainly no secret value —
 * is ever hardcoded here.
 *
 * AWS Secrets Manager notes
 * ──────────────────────────
 * • Each key from .env.test is expected to exist as its own secret in Secrets
 *   Manager (SecretId == the key name, e.g. "DATABASE_URL").
 * • Alternatively, all secrets can be stored as a single JSON secret whose
 *   SecretId is controlled by the SM_SECRET_ID env-var (default: "app/secrets").
 *   When that variable is set the module fetches once and fans out by key.
 * • The AWS region is read from AWS_REGION (default: "us-east-1").
 */

'use strict';

const path = require('path');
const fs   = require('fs');

// ---------------------------------------------------------------------------
// 1.  Parse .env.test to discover required secret names (keys only, no values
//     are retained after the key-list is built).
// ---------------------------------------------------------------------------

const ENV_TEST_PATH = path.resolve(__dirname, '.env.test');

/**
 * Returns the ordered list of secret key names declared in .env.test.
 * Values are intentionally discarded unless we are in the local-fallback path.
 *
 * @returns {string[]}
 */
function parseEnvKeys(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  const keys = [];
  for (const rawLine of content.split('\n')) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;          // skip comments / blanks
    const eqIdx = line.indexOf('=');
    if (eqIdx < 1) continue;                              // malformed line
    keys.push(line.slice(0, eqIdx).trim());
  }
  return keys;
}

/** All secret names this application requires, derived solely from .env.test keys. */
const REQUIRED_SECRET_NAMES = parseEnvKeys(ENV_TEST_PATH);

// ---------------------------------------------------------------------------
// 2.  Lazy-loaded local fallback map (values only read from disk when needed).
// ---------------------------------------------------------------------------

let _localFallback = null; // { KEY: 'value', … } — populated on first use

/**
 * Parses .env.test fully (keys + values) into a plain object.
 * Called only when the local fallback path is actually exercised.
 *
 * @returns {Record<string, string>}
 */
function loadLocalFallback() {
  if (_localFallback) return _localFallback;

  // dotenv.parse reads the file and returns { KEY: value } without touching
  // process.env, which keeps our process environment clean.
  const dotenv = require('dotenv');
  const buf    = fs.readFileSync(ENV_TEST_PATH);
  _localFallback = dotenv.parse(buf);
  return _localFallback;
}

// ---------------------------------------------------------------------------
// 3.  AWS Secrets Manager client (lazily instantiated).
// ---------------------------------------------------------------------------

let _smClient = null;

function getSecretsManagerClient() {
  if (_smClient) return _smClient;
  const { SecretsManagerClient } = require('@aws-sdk/client-secrets-manager');
  _smClient = new SecretsManagerClient({
    region: process.env.AWS_REGION || 'us-east-1',
  });
  return _smClient;
}

// ---------------------------------------------------------------------------
// 4.  Core secret-fetching logic.
// ---------------------------------------------------------------------------

/**
 * Attempt to retrieve a single secret value from AWS Secrets Manager.
 *
 * Strategy
 * ─────────
 * • If SM_SECRET_ID is set, all secrets are assumed to live inside one JSON
 *   blob stored under that id.  We fetch once, parse, and return the field
 *   matching `name`.
 * • Otherwise each secret name maps 1-to-1 to its own SecretId.
 *
 * @param {string} name  The secret key name (e.g. "DATABASE_URL")
 * @returns {Promise<string>}  Resolves with the plaintext secret value.
 * @throws  If the secret cannot be found or the response is malformed.
 */
async function fetchFromSecretsManager(name) {
  const { GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
  const client = getSecretsManagerClient();

  const secretId = process.env.SM_SECRET_ID || name;
  const command  = new GetSecretValueCommand({ SecretId: secretId });
  const response = await client.send(command);

  const raw = response.SecretString ?? response.SecretBinary?.toString('utf8');
  if (!raw) {
    throw new Error(`[secrets] Empty response from Secrets Manager for: ${secretId}`);
  }

  // If the caller provided SM_SECRET_ID we expect a JSON bundle; otherwise the
  // secret string IS the value (plain text).
  if (process.env.SM_SECRET_ID) {
    let bundle;
    try {
      bundle = JSON.parse(raw);
    } catch {
      throw new Error(
        `[secrets] SM_SECRET_ID="${secretId}" response is not valid JSON. ` +
        'Store all secrets as a JSON object or unset SM_SECRET_ID to use per-key secrets.'
      );
    }
    if (!(name in bundle)) {
      throw new Error(
        `[secrets] Key "${name}" not found in Secrets Manager bundle "${secretId}".`
      );
    }
    return bundle[name];
  }

  return raw;
}

// ---------------------------------------------------------------------------
// 5.  Public API
// ---------------------------------------------------------------------------

/**
 * Whether the local .env.test fallback is permitted.
 *
 * Enabled when:
 *   • NODE_ENV is "development" (or not set), OR
 *   • ALLOW_LOCAL_FALLBACK=true is explicitly set.
 *
 * In production (NODE_ENV=production) the fallback is disabled unless the
 * operator explicitly opts in via ALLOW_LOCAL_FALLBACK=true.
 */
function isLocalFallbackAllowed() {
  const env = (process.env.NODE_ENV || 'development').toLowerCase();
  if (env === 'development' || env === 'test') return true;
  return (process.env.ALLOW_LOCAL_FALLBACK || '').toLowerCase() === 'true';
}

/**
 * Fetches the value for `name` from AWS Secrets Manager.
 * Falls back to .env.test when running locally or when Secrets Manager is
 * unreachable and the fallback is explicitly permitted.
 *
 * @param {string} name  Secret key name (must be listed in .env.test).
 * @returns {Promise<string>}
 * @throws  When the secret cannot be resolved from any source.
 */
async function getSecret(name) {
  if (!REQUIRED_SECRET_NAMES.includes(name)) {
    throw new Error(
      `[secrets] "${name}" is not a recognised secret. ` +
      `Known secrets: ${REQUIRED_SECRET_NAMES.join(', ')}`
    );
  }

  // --- attempt Secrets Manager first ---
  try {
    const value = await fetchFromSecretsManager(name);
    return value;
  } catch (smError) {
    if (!isLocalFallbackAllowed()) {
      // Re-throw in production so the failure is loud and explicit.
      throw new Error(
        `[secrets] Failed to fetch "${name}" from Secrets Manager and ` +
        `local fallback is disabled (NODE_ENV=${process.env.NODE_ENV}). ` +
        `Original error: ${smError.message}`
      );
    }
    console.warn(
      `[secrets] Secrets Manager unavailable for "${name}", falling back to .env.test. ` +
      `(${smError.message})`
    );
  }

  // --- local .env.test fallback ---
  const local = loadLocalFallback();
  if (name in local) {
    return local[name];
  }

  throw new Error(
    `[secrets] "${name}" not found in Secrets Manager or .env.test fallback.`
  );
}

/**
 * Pre-fetches every required secret and returns them as a plain object.
 * Useful at application start-up to fail fast if any secret is missing.
 *
 * @returns {Promise<Record<string, string>>}
 */
async function loadAllSecrets() {
  const entries = await Promise.all(
    REQUIRED_SECRET_NAMES.map(async (name) => [name, await getSecret(name)])
  );
  return Object.fromEntries(entries);
}

module.exports = {
  /** Ordered list of secret names derived from .env.test keys. */
  REQUIRED_SECRET_NAMES,
  /** Fetch a single secret by name. */
  getSecret,
  /** Fetch all required secrets at once — recommended at startup. */
  loadAllSecrets,
};

// app.js — application entry-point.
// Secrets are resolved through secrets.js; no values are hardcoded here.

'use strict';

const express = require('express');
const { loadAllSecrets, getSecret } = require('./secrets');

const app = express();

// ---------------------------------------------------------------------------
// Bootstrap: resolve all secrets before opening the server to traffic.
// Any missing / unreachable secret will throw here, preventing a half-started
// server from accepting requests with invalid credentials.
// ---------------------------------------------------------------------------

async function bootstrap() {
  // Load every secret declared in .env.test in one shot.
  // In production these come from AWS Secrets Manager; locally they fall back
  // to .env.test values (see secrets.js for the full resolution rules).
  const secrets = await loadAllSecrets();

  // Expose secrets to the rest of the application via the module-level object.
  // Nothing is placed on process.env to avoid accidental leakage through
  // environment dumps or child-process inheritance.
  app.locals.secrets = secrets;

  // --- Database (example usage) ---
  // const db = new DatabaseClient({ connectionString: secrets.DATABASE_URL });
  // await db.connect();

  // --- Stripe (example usage) ---
  // const stripe = require('stripe')(secrets.STRIPE_SECRET_KEY);

  // --- Anthropic (example usage) ---
  // const anthropic = new Anthropic({ apiKey: secrets.ANTHROPIC_API_KEY });

  return secrets;
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// Example: an endpoint that uses a secret at request time via getSecret().
// This pattern is useful when you want per-request refresh semantics rather
// than a single value cached at startup.
app.get('/integrations/status', async (req, res) => {
  try {
    // Fetch only what this handler needs — getSecret() is memoised at the
    // Secrets Manager level and falls back to .env.test when appropriate.
    const logfireToken = await getSecret('LOGFIRE_TOKEN');

    // Use the token (e.g. to query a logging service status endpoint).
    // The value is never echoed back in the response.
    const hasToken = Boolean(logfireToken);

    res.json({ logfire: hasToken ? 'configured' : 'missing' });
  } catch (err) {
    console.error('[/integrations/status]', err.message);
    res.status(500).json({ error: 'Could not resolve integration credentials.' });
  }
});

// ---------------------------------------------------------------------------
// Start
// ---------------------------------------------------------------------------

async function start() {
  await bootstrap();
  app.listen(3000, () => {
    console.log('Server running on port 3000');
  });
}

// Only call start() when this file is run directly (not when required by tests).
if (require.main === module) {
  start().catch((err) => {
    console.error('[startup] Fatal — could not resolve secrets:', err.message);
    process.exit(1);
  });
}

module.exports = app;

