/**
 * Parses .env.test fully (keys + values) into a plain object.
 * Called only when the local fallback path is actually exercised.
 *
 * Uses dotenv.parse when available; falls back to a built-in parser that
 * handles the same subset of the .env format (comments, blank lines, optional
 * surrounding quotes) so the module works even before `npm install`.
 *
 * In neither case are values written to process.env.
 *
 * @returns {Record<string, string>}
 */
function loadLocalFallback() {
  if (_localFallback) return _localFallback;

  const raw = fs.readFileSync(ENV_TEST_PATH, 'utf8');

  // Prefer dotenv.parse when the package is available.
  try {
    const dotenv = require('dotenv');
    _localFallback = dotenv.parse(raw);
    return _localFallback;
  } catch {
    // dotenv not installed — use the built-in parser below.
  }

  // Built-in .env parser: handles comments, blank lines, and values that are
  // optionally wrapped in single or double quotes.
  const result = {};
  for (const rawLine of raw.split('\n')) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;
    const eqIdx = line.indexOf('=');
    if (eqIdx < 1) continue;
    const key = line.slice(0, eqIdx).trim();
    let val   = line.slice(eqIdx + 1).trim();
    // Strip optional surrounding quotes.
    if ((val.startsWith('"') && val.endsWith('"')) ||
        (val.startsWith("'") && val.endsWith("'"))) {
      val = val.slice(1, -1);
    }
    result[key] = val;
  }
  _localFallback = result;
  return _localFallback;
}

