/**
 * secrets.js
 *
 * Centralised secret-loading module.
 *
 * Resolution order for every secret name:
 *   1. AWS Secrets Manager  (when NODE_ENV !== 'development' OR when
 *      USE_AWS_SECRETS=true is explicitly set)
 *   2. Local .env.test file via dotenv  (fallback for development only)
 *
 * The module reads *only the key names* from .env.test at startup so that
 * it knows which secrets are required.  Values are never logged, embedded
 * in source, or transmitted anywhere other than to the caller via
 * getSecret().
 *
 * Required npm packages:
 *   npm install @aws-sdk/client-secrets-manager dotenv
 */

'use strict';

const path = require('path');
const fs   = require('fs');
const {
  SecretsManagerClient,
  GetSecretValueCommand,
} = require('@aws-sdk/client-secrets-manager');
const dotenv = require('dotenv');

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

/** Path to the local env file used as a development fallback. */
const ENV_FILE = path.resolve(__dirname, '.env.test');

/**
 * AWS region for Secrets Manager.
 * Override via the AWS_REGION environment variable.
 */
const AWS_REGION = process.env.AWS_REGION || 'us-east-1';

/**
 * When true, always contact AWS Secrets Manager even in development.
 * Set USE_AWS_SECRETS=true in the shell to force this behaviour.
 */
const USE_AWS_SECRETS =
  process.env.USE_AWS_SECRETS === 'true' ||
  (process.env.NODE_ENV && process.env.NODE_ENV !== 'development');

// ---------------------------------------------------------------------------
// 1. Discover required secret names from .env.test (names only, not values)
// ---------------------------------------------------------------------------

/**
 * Parse a dotenv-style file and return only the variable *names* defined in
 * it.  Values are intentionally discarded here so this function can be used
 * safely for introspection without touching secret material.
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {string[]} Sorted array of variable names.
 */
function parseSecretNames(filePath) {
  if (!fs.existsSync(filePath)) {
    console.warn(`[secrets] Warning: env file not found at ${filePath}`);
    return [];
  }

  const raw = fs.readFileSync(filePath, 'utf8');
  const names = [];

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    // Skip blank lines and comments
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex > 0) {
      names.push(trimmed.slice(0, eqIndex).trim());
    }
  }

  return names.sort();
}

/** The list of secret names that this application requires. */
const REQUIRED_SECRET_NAMES = parseSecretNames(ENV_FILE);

if (REQUIRED_SECRET_NAMES.length === 0) {
  console.warn('[secrets] Warning: no secret names discovered from env file.');
} else {
  console.info(
    `[secrets] Discovered ${REQUIRED_SECRET_NAMES.length} required secret(s): ` +
    REQUIRED_SECRET_NAMES.join(', ')
  );
}

// ---------------------------------------------------------------------------
// 2. AWS Secrets Manager client (lazy-initialised)
// ---------------------------------------------------------------------------

/** @type {SecretsManagerClient|null} */
let smClient = null;

/**
 * Returns a shared SecretsManagerClient, creating it on the first call.
 * Credentials are resolved automatically by the AWS SDK in this order:
 *   - Environment variables (AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY)
 *   - Shared credentials file (~/.aws/credentials)
 *   - IAM instance / task role  (recommended for production)
 *
 * @returns {SecretsManagerClient}
 */
function getSmClient() {
  if (!smClient) {
    smClient = new SecretsManagerClient({ region: AWS_REGION });
  }
  return smClient;
}

// ---------------------------------------------------------------------------
// 3. In-memory cache — avoids redundant API calls within a single process
// ---------------------------------------------------------------------------

/** @type {Map<string, string>} */
const secretCache = new Map();

// ---------------------------------------------------------------------------
// 4. dotenv fallback loader (development only)
// ---------------------------------------------------------------------------

/**
 * Lazily-loaded dotenv values for development fallback.
 * Populated on first access via loadEnvFallback().
 * @type {Record<string,string>|null}
 */
let envFallbackValues = null;

/**
 * Load the .env.test file through dotenv into a local object so that the
 * values are available for the fallback path *without* polluting
 * process.env.
 *
 * @returns {Record<string,string>}
 */
function loadEnvFallback() {
  if (envFallbackValues !== null) return envFallbackValues;

  const result = dotenv.config({ path: ENV_FILE, processEnv: {} });

  if (result.error) {
    console.warn(`[secrets] dotenv fallback could not load ${ENV_FILE}: ${result.error.message}`);
    envFallbackValues = {};
  } else {
    // result.parsed contains { KEY: value } pairs — kept entirely in memory,
    // never logged or exported.
    envFallbackValues = result.parsed || {};
  }

  return envFallbackValues;
}

// ---------------------------------------------------------------------------
// 5. Core getSecret() function
// ---------------------------------------------------------------------------

/**
 * Retrieve the value of a named secret.
 *
 * Resolution order:
 *   a) In-process cache (fastest; avoids repeated API / file reads)
 *   b) AWS Secrets Manager  (when USE_AWS_SECRETS is true)
 *   c) Local .env.test file  (development fallback only)
 *
 * @param {string} name - The secret name / key, e.g. 'DATABASE_URL'.
 * @returns {Promise<string>} Resolves to the secret value.
 * @throws {Error} If the secret cannot be found by any resolver.
 */
async function getSecret(name) {
  if (!name || typeof name !== 'string') {
    throw new TypeError(`[secrets] getSecret() requires a non-empty string name, got: ${name}`);
  }

  // (a) Cache hit
  if (secretCache.has(name)) {
    return secretCache.get(name);
  }

  // (b) AWS Secrets Manager
  if (USE_AWS_SECRETS) {
    try {
      const value = await fetchFromSecretsManager(name);
      secretCache.set(name, value);
      return value;
    } catch (err) {
      // Re-throw in production; fall through to local file in development
      if (process.env.NODE_ENV !== 'development') {
        throw new Error(
          `[secrets] Failed to retrieve "${name}" from AWS Secrets Manager: ${err.message}`
        );
      }
      console.warn(
        `[secrets] AWS Secrets Manager unavailable for "${name}", ` +
        `falling back to local file. Error: ${err.message}`
      );
    }
  }

  // (c) Local .env.test fallback (development / CI)
  const fallback = loadEnvFallback();
  if (Object.prototype.hasOwnProperty.call(fallback, name)) {
    const value = fallback[name];
    secretCache.set(name, value);
    return value;
  }

  throw new Error(
    `[secrets] Secret "${name}" not found in AWS Secrets Manager or local env file. ` +
    `Available names: ${REQUIRED_SECRET_NAMES.join(', ')}`
  );
}

// ---------------------------------------------------------------------------
// 6. AWS Secrets Manager fetch helper
// ---------------------------------------------------------------------------

/**
 * Fetch a single secret string from AWS Secrets Manager.
 *
 * Secrets Manager can store a secret as a plain string or as a JSON object.
 * If the stored value is valid JSON, the function returns the raw JSON string
 * so the caller can parse it; if a specific key within a JSON secret is
 * needed, pass `name` as "MySecret/KEY" (see parseSecretName() below).
 *
 * @param {string} name - Secret name or ARN.
 * @returns {Promise<string>}
 */
async function fetchFromSecretsManager(name) {
  // Support "SecretName/JSON_KEY" notation to extract a single field from a
  // JSON secret, e.g. "MyAppSecrets/DATABASE_URL".
  const { secretId, jsonKey } = parseSecretName(name);

  const command = new GetSecretValueCommand({ SecretId: secretId });
  const response = await getSmClient().send(command);

  // Secrets Manager returns either SecretString or SecretBinary
  let rawValue;
  if (typeof response.SecretString === 'string') {
    rawValue = response.SecretString;
  } else if (response.SecretBinary) {
    rawValue = Buffer.from(response.SecretBinary).toString('utf8');
  } else {
    throw new Error(`[secrets] Secrets Manager returned no value for "${secretId}"`);
  }

  // If a JSON sub-key was requested, parse and extract it
  if (jsonKey) {
    let parsed;
    try {
      parsed = JSON.parse(rawValue);
    } catch {
      throw new Error(
        `[secrets] Secret "${secretId}" is not valid JSON; cannot extract key "${jsonKey}"`
      );
    }
    if (!Object.prototype.hasOwnProperty.call(parsed, jsonKey)) {
      throw new Error(`[secrets] JSON secret "${secretId}" has no key "${jsonKey}"`);
    }
    return parsed[jsonKey];
  }

  return rawValue;
}

/**
 * Split an optional "SecretId/JsonKey" notation into its two components.
 *
 * Examples:
 *   "DATABASE_URL"               → { secretId: "DATABASE_URL", jsonKey: null }
 *   "MyAppSecrets/DATABASE_URL"  → { secretId: "MyAppSecrets", jsonKey: "DATABASE_URL" }
 *
 * @param {string} name
 * @returns {{ secretId: string, jsonKey: string|null }}
 */
function parseSecretName(name) {
  const slashIndex = name.indexOf('/');
  if (slashIndex === -1) {
    return { secretId: name, jsonKey: null };
  }
  return {
    secretId: name.slice(0, slashIndex),
    jsonKey:  name.slice(slashIndex + 1),
  };
