// 7. Bulk pre-loader — warm the cache at startup (optional)
// ---------------------------------------------------------------------------

/**
 * Pre-fetch all required secrets and warm the in-process cache.
 * Call this once during application startup to surface missing-secret errors
 * early rather than at request time.
 *
 * @returns {Promise<void>}
 * @throws {Error} Aggregated error listing every secret that could not be loaded.
 */
async function loadAllSecrets() {
  if (REQUIRED_SECRET_NAMES.length === 0) {
    console.warn('[secrets] loadAllSecrets(): no secrets to load.');
    return;
  }

  const errors = [];

  await Promise.all(
    REQUIRED_SECRET_NAMES.map(async (name) => {
      try {
        await getSecret(name);
        // Do NOT log the value — only confirm the name was resolved
        console.info(`[secrets] ✓ Loaded secret: ${name}`);
      } catch (err) {
        errors.push(err.message);
        console.error(`[secrets] ✗ Failed to load secret: ${name} — ${err.message}`);
      }
    })
  );

  if (errors.length > 0) {
    throw new Error(
      `[secrets] ${errors.length} secret(s) could not be loaded:\n` +
      errors.map((e) => `  • ${e}`).join('\n')
    );
  }

  console.info('[secrets] All secrets loaded successfully.');
}

// ---------------------------------------------------------------------------
// 8. Exports
// ---------------------------------------------------------------------------

module.exports = {
  /** Fetch a secret by name (async). */
  getSecret,

  /** Pre-warm the cache for all required secrets (async). */
  loadAllSecrets,

  /**
   * The list of required secret names discovered from .env.test.
   * Contains names only — never values.
   * @type {string[]}
   */
  REQUIRED_SECRET_NAMES,
