  // loadAllSecrets() fetches every secret listed in .env.test from AWS
  // Secrets Manager (or the local fallback) and caches them in memory.
  // The process exits immediately if any required secret is unavailable,
  // preventing the server from starting in a misconfigured state.
  await loadAllSecrets();

  // ---------------------------------------------------------------------------
  // Routes
  // ---------------------------------------------------------------------------

  app.get('/health', (req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  });

  app.get('/users', (req, res) => {
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ]);
  });

  // Example: use a secret inside a route handler.
  // getSecret() returns instantly after the first call because the value
  // is already in the in-process cache populated by loadAllSecrets() above.
  app.get('/db-check', async (req, res) => {
    try {
      const dbUrl = await getSecret('DATABASE_URL');

      // Use the secret value (e.g. open a DB connection, run a ping query).
      // Here we only confirm the URL was resolved; never echo the value back.
      const isResolved = typeof dbUrl === 'string' && dbUrl.length > 0;

      res.json({ database_configured: isResolved });
    } catch (err) {
      res.status(500).json({ error: 'Could not resolve DATABASE_URL secret.' });
    }
  });

  // ---------------------------------------------------------------------------
  // Listen
  // ---------------------------------------------------------------------------

  app.listen(3000, () => {
    console.log('Server running on port 3000');
  });
}

// ---------------------------------------------------------------------------
// Boot
// ---------------------------------------------------------------------------

startServer().catch((err) => {
  console.error('Fatal: server failed to start.\n', err.message);
  process.exit(1);
});

module.exports = app;

