/**
 * Returns an array of secret key names declared in the env file.
 * Only the key names are read; values are intentionally discarded.
 *
 * @param {string} filePath  Absolute path to the env file.
 * @returns {string[]}
 */
function readSecretNames(filePath) {
  if (!fs.existsSync(filePath)) {
    return [];
  }
  const lines = fs.readFileSync(filePath, 'utf8').split(/\r?\n/);
  const names = [];
  for (const line of lines) {
    const trimmed = line.trim();
    // Skip blank lines and comments
    if (!trimmed || trimmed.startsWith('#')) continue;
    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue;
    names.push(trimmed.slice(0, eqIndex).trim());
  }
  return names;
}

/** All secret key names this application expects. */
