function buildSdkStub({ SecretString, throws }) {
  class SecretsManagerClient {
    async send() {
      if (throws) throw new Error(throws);
      return { SecretString };
    }
  }
  class GetSecretValueCommand {
    constructor(params) { this.params = params; }
  }
  return { SecretsManagerClient, GetSecretValueCommand };
}

// Sentinel key used in require.cache to hold the SDK stub
const SDK_MODULE_ID = '@aws-sdk/client-secrets-manager';

/**
 * Injects a fake SDK module into require.cache under a stable key so that
 * any require('@aws-sdk/client-secrets-manager') inside secrets.js returns
 * our stub instead of the real (uninstalled) package.
 */
function injectSdkStub(stub) {
  // Build a synthetic resolved path so Node accepts it as a cache key
  const fakeId = path.join(__dirname, 'node_modules', SDK_MODULE_ID, 'index.js');
  const mod = new Module(fakeId);
  mod.exports = buildSdkStub(stub);
  mod.loaded = true;
  mod.filename = fakeId;

  // Also patch _resolveFilename so require(SDK_MODULE_ID) resolves to fakeId
  const origResolve = Module._resolveFilename;
  Module._resolveFilename = function (request, ...rest) {
    if (request === SDK_MODULE_ID) return fakeId;
    return origResolve.call(this, request, ...rest);
  };

  require.cache[fakeId] = mod;

  // Return a cleanup function
  return function cleanup() {
    Module._resolveFilename = origResolve;
    delete require.cache[fakeId];
  };
}

