/**
 * Loads a fresh (uncached) copy of secrets.js with the given environment and
 * optional stub for @aws-sdk/client-secrets-manager.
 *
 * @param {object} env          Values to set on process.env for this load.
 * @param {object} [smStub]     Optional stub: { SecretString } or { throws }
 * @returns {object}            The secrets module exports.
 */
function loadSecrets(env = {}, smStub = null) {
  // 1. Apply env overrides (save originals)
  const saved = {};
  const MANAGED_KEYS = [
    'NODE_ENV', 'AWS_REGION', 'AWS_SM_SECRET_ID', 'APP_SECRET_ID',
    'ENV_FILE', 'USE_SECRETS_MANAGER', 'ALLOW_LOCAL_FALLBACK',
  ];
  for (const k of MANAGED_KEYS) {
    saved[k] = process.env[k];
    delete process.env[k];
  }
  for (const [k, v] of Object.entries(env)) {
    process.env[k] = v;
  }

  // 2. Remove cached module so we get a fresh require
  const secretsPath = require.resolve('./secrets');
  delete require.cache[secretsPath];

  // 3. Inject the SDK stub into require.cache if provided
  let cleanupStub = null;
  if (smStub !== null) {
    cleanupStub = injectSdkStub(smStub);
  }

  let mod;
  try {
    mod = require('./secrets');
  } finally {
    // Restore env
    for (const k of MANAGED_KEYS) {
      if (saved[k] === undefined) delete process.env[k];
      else process.env[k] = saved[k];
    }
    // Clean up stub (after secrets.js is loaded; the stub stays in cache for
    // async calls that happen later via the returned module)
  }

  // Return a wrapper that also cleans up the stub cache entry when done.
  // For simplicity in these tests we clean up after each async test call.
  mod._cleanupStub = cleanupStub || (() => {});
  return mod;
}

