{
  "name": "p15-test-v1rsgn",
  "version": "1.0.0",
  "description": "",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "test": "echo \"Error: no test specified\" && exit 1"
  },
  "keywords": [],
  "author": "",
  "license": "ISC",
  "dependencies": {
    "@aws-sdk/client-secrets-manager": "^3.0.0",
    "dotenv": "^16.0.0",
    "express": "^4.18.0"
  }
}

/**
 * secrets.js
 *
 * Centralised secret-loading module.
 *
 * Strategy
 * --------
 * Production  → AWS Secrets Manager (one API call per secret name).
 * Development → Falls back to values in .env.test when
 *               (a) NODE_ENV is "development" or "test", OR
 *               (b) the Secrets Manager call fails (e.g. no network / no IAM
 *               role) so local dev always works without AWS credentials.
 *
 * Secret names
 * ------------
 * The canonical list of required secret names is derived at startup by
 * reading the *keys* from .env.test — no values are ever read from that
 * file in production.  This means adding a new secret only requires:
 *   1. Adding its name (and a canary/dev value) to .env.test.
 *   2. Storing the real value in AWS Secrets Manager under the same name.
 *
 * AWS secret storage format
 * -------------------------
 * Each secret is expected to be stored as a Secrets Manager secret whose
 * *name* matches the key from .env.test (e.g. "DATABASE_URL") and whose
 * *secret value* is a plain string.  A JSON-encoded string is also
 * accepted; if the value parses as JSON the module returns the inner
 * string so callers always receive a plain string.
 *
 * Usage
 * -----
 *   const { getSecret, requiredSecretNames } = require('./secrets');
 *
 *   // Fetch one secret (async):
 *   const dbUrl = await getSecret('DATABASE_URL');
 *
 *   // Inspect which names were discovered from .env.test:
 *   console.log(requiredSecretNames);
 */

'use strict';

const path = require('path');
const fs   = require('fs');

// ---------------------------------------------------------------------------
// 1. Parse .env.test to discover required secret *names* (not values).
//    We do our own lightweight parse so we do not accidentally leak values
//    into process.env at import time.
// ---------------------------------------------------------------------------

const ENV_FILE = path.resolve(__dirname, '.env.test');

/**
 * Parses a .env-style file and returns a plain object of key→value pairs.
 * Lines that are blank or start with # are ignored.
 * Values may optionally be wrapped in single or double quotes.
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {Record<string, string>}
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return {};
  }

  const lines  = fs.readFileSync(filePath, 'utf8').split('\n');
  const result = {};

  for (const raw of lines) {
    const line = raw.trim();

    // Skip blank lines and comments.
    if (!line || line.startsWith('#')) continue;

    const eqIndex = line.indexOf('=');
    if (eqIndex === -1) continue;

    const key = line.slice(0, eqIndex).trim();
    let   val = line.slice(eqIndex + 1).trim();

    // Strip optional surrounding quotes.
    if (
      (val.startsWith('"') && val.endsWith('"')) ||
      (val.startsWith("'") && val.endsWith("'"))
    ) {
      val = val.slice(1, -1);
    }

    if (key) result[key] = val;
  }

  return result;
}

/** All key names found in .env.test (values are NOT exported). */
const _envFileEntries     = parseEnvFile(ENV_FILE);
const requiredSecretNames = Object.keys(_envFileEntries);

// ---------------------------------------------------------------------------
// 2. AWS Secrets Manager client (lazy-initialised so the module can be
//    imported without AWS credentials during unit tests).
// ---------------------------------------------------------------------------

let _smClient = null;

/**
 * Returns a (cached) SecretsManagerClient.
 * Importing the SDK here, inside a function, means the module still loads
 * cleanly even when the package is not yet installed — you just cannot call
 * getSecret() in that case without installing dependencies first.
 *
 * @returns {import('@aws-sdk/client-secrets-manager').SecretsManagerClient}
 */
function getSmClient() {
  if (_smClient) return _smClient;

  // eslint-disable-next-line global-require
  const { SecretsManagerClient } = require('@aws-sdk/client-secrets-manager');

  _smClient = new SecretsManagerClient({
    // Region is read from AWS_REGION / AWS_DEFAULT_REGION env vars (standard
    // AWS SDK behaviour) or falls back to us-east-1.
    region: process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION || 'us-east-1',
  });

  return _smClient;
}

// ---------------------------------------------------------------------------
// 3. In-process cache so each unique secret name is fetched at most once
//    per process lifetime.
// ---------------------------------------------------------------------------

/** @type {Map<string, string>} */
const _cache = new Map();

// ---------------------------------------------------------------------------
// 4. Core helper — fetch a single secret from Secrets Manager.
// ---------------------------------------------------------------------------

/**
 * Fetches the value of a single secret from AWS Secrets Manager.
 *
 * @param {string} name - The Secrets Manager secret name (or ARN).
 * @returns {Promise<string>} The secret's string value.
 * @throws {Error} If the secret cannot be retrieved from Secrets Manager.
 */
async function fetchFromSecretsManager(name) {
  // eslint-disable-next-line global-require
  const { GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

  const command  = new GetSecretValueCommand({ SecretId: name });
  const response = await getSmClient().send(command);

  // Secrets Manager can return the value as either SecretString (text/JSON)
  // or SecretBinary (base64-encoded binary).  We only handle string secrets.
  const raw = response.SecretString;
  if (raw === undefined || raw === null) {
    throw new Error(
      `Secret "${name}" was found in Secrets Manager but contains no SecretString. ` +
      'Binary secrets are not supported.'
    );
  }

  // If the caller stored the value as a JSON-encoded string unwrap it so
  // callers always receive a plain string regardless of how it was stored.
  try {
    const parsed = JSON.parse(raw);
    if (typeof parsed === 'string') return parsed;
    // If the JSON value is an object/array return as-is (stringified) so
    // callers receive something predictable.
    return raw;
  } catch {
    // Not JSON — return the raw string directly.
    return raw;
  }
}

// ---------------------------------------------------------------------------
// 5. Public API
// ---------------------------------------------------------------------------

/**
 * Returns the value of a secret.
 *
 * Lookup order:
 *   1. In-process cache (avoids redundant API calls within a single run).
 *   2. AWS Secrets Manager          — used when NODE_ENV is not "development"
 *                                     or "test" AND the call succeeds.
 *   3. .env.test fallback           — used when:
 *        • NODE_ENV === "development" or "test", OR
 *        • the Secrets Manager call throws (e.g. network error, missing
 *          IAM permission) so a missing AWS setup never breaks local dev.
 *
 * @param {string} name - The secret name, matching a key in .env.test.
 * @returns {Promise<string>} The resolved secret value.
 * @throws {Error} If the secret cannot be found via any strategy.
 */
async function getSecret(name) {
  // -- 1. Cache hit --------------------------------------------------------
  if (_cache.has(name)) {
    return _cache.get(name);
  }

  const isLocalEnv = ['development', 'test'].includes(
    (process.env.NODE_ENV || '').toLowerCase()
  );

  // -- 2. AWS Secrets Manager (non-local environments) ---------------------
  if (!isLocalEnv) {
    try {
      const value = await fetchFromSecretsManager(name);
      _cache.set(name, value);
      return value;
    } catch (err) {
      // Surface infrastructure errors loudly in production — a misconfigured
      // secret in prod should not silently fall back to a canary/dev value.
      console.error(
        `[secrets] ERROR: Failed to fetch secret "${name}" from AWS Secrets Manager ` +
        `in non-local environment (NODE_ENV="${process.env.NODE_ENV}"). ` +
        `Attempting .env.test fallback. Error: ${err.message}`
      );
      // Fall through to local fallback below — you may want to throw here
      // in a strict production setup to prevent startup with wrong secrets.
    }
  }

  // -- 3. Local .env.test fallback -----------------------------------------
  if (Object.prototype.hasOwnProperty.call(_envFileEntries, name)) {
    const value = _envFileEntries[name];

    if (isLocalEnv) {
      console.debug(`[secrets] Using .env.test value for "${name}" (local environment).`);
    } else {
      console.warn(
        `[secrets] WARNING: Falling back to .env.test value for "${name}". ` +
        'This should not happen in production.'
      );
    }

    _cache.set(name, value);
    return value;
  }

  // -- Nothing worked -------------------------------------------------------
  throw new Error(
    `Secret "${name}" could not be resolved. ` +
    'It is not present in AWS Secrets Manager (or the call failed) and ' +
    'it is not defined in .env.test. ' +
    `Known secret names: [${requiredSecretNames.join(', ')}]`
  );
}

// ---------------------------------------------------------------------------
// 6. Warm-up helper (optional — call at startup to pre-fetch all secrets
//    and surface any misconfiguration before the first request arrives).
// ---------------------------------------------------------------------------

/**
 * Pre-fetches every secret listed in .env.test and populates the cache.
 * Useful to call once during application startup so any Secrets Manager
 * misconfigurations fail fast rather than at request time.
 *
 * @returns {Promise<Record<string, string>>} Map of name → resolved value.
 */
async function loadAllSecrets() {
  const entries = await Promise.all(
    requiredSecretNames.map(async (name) => {
      const value = await getSecret(name);
      return [name, value];
    })
  );
  return Object.fromEntries(entries);
}

// ---------------------------------------------------------------------------

module.exports = {
  /** Fetch (and cache) a single secret by name. */
  getSecret,
  /** Pre-fetch every required secret into the cache. */
  loadAllSecrets,
  /** The ordered list of secret names discovered from .env.test. */
  requiredSecretNames,
};

/**
 * app.js
 *
 * Application entry point.
 *
 * Secrets are never read directly from environment variables or .env files
 * here.  All secret access goes through the `secrets` module, which handles
 * the AWS Secrets Manager ↔ local fallback strategy transparently.
 */

'use strict';

const express               = require('express');
const { getSecret, loadAllSecrets, requiredSecretNames } = require('./secrets');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Startup: pre-fetch all secrets so misconfiguration surfaces immediately.
// The resolved values are kept inside the secrets module's cache; call
// getSecret(name) anywhere in the codebase to retrieve them without an
// additional network round-trip.
// ---------------------------------------------------------------------------

async function start() {
  console.log(
    `[app] Loading ${requiredSecretNames.length} secret(s): ${requiredSecretNames.join(', ')}`
  );

