 *
 * Secret names
 * ------------
 * The canonical list of required secret names is derived at startup by
 * reading the *keys* from .env.test — no values are ever read from that
 * file in production.  This means adding a new secret only requires:
 *   1. Adding its name (and a canary/dev value) to .env.test.
 *   2. Storing the real value in AWS Secrets Manager under the same name.
 *
 * AWS secret storage format
 * -------------------------
 * Each secret is expected to be stored as a Secrets Manager secret whose
 * *name* matches the key from .env.test (e.g. "DATABASE_URL") and whose
 * *secret value* is a plain string.  A JSON-encoded string is also
 * accepted; if the value parses as JSON the module returns the inner
 * string so callers always receive a plain string.
 *
 * Usage
 * -----
 *   const { getSecret, requiredSecretNames } = require('./secrets');
 *
 *   // Fetch one secret (async):
 *   const dbUrl = await getSecret('DATABASE_URL');
 *
 *   // Inspect which names were discovered from .env.test:
 *   console.log(requiredSecretNames);
 */

'use strict';

const path = require('path');
const fs   = require('fs');

// ---------------------------------------------------------------------------
// 1. Parse .env.test to discover required secret *names* (not values).
//    We do our own lightweight parse so we do not accidentally leak values
//    into process.env at import time.
// ---------------------------------------------------------------------------

const ENV_FILE = path.resolve(__dirname, '.env.test');

/**
 * Parses a .env-style file and returns a plain object of key→value pairs.
 * Lines that are blank or start with # are ignored.
 * Values may optionally be wrapped in single or double quotes.
 *
 * @param {string} filePath - Absolute path to the .env file.
 * @returns {Record<string, string>}
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return {};
  }

  const lines  = fs.readFileSync(filePath, 'utf8').split('\n');
  const result = {};

  for (const raw of lines) {
    const line = raw.trim();

    // Skip blank lines and comments.
    if (!line || line.startsWith('#')) continue;

    const eqIndex = line.indexOf('=');
    if (eqIndex === -1) continue;

    const key = line.slice(0, eqIndex).trim();
    let   val = line.slice(eqIndex + 1).trim();

    // Strip optional surrounding quotes.
    if (
      (val.startsWith('"') && val.endsWith('"')) ||
      (val.startsWith("'") && val.endsWith("'"))
    ) {
      val = val.slice(1, -1);
    }

    if (key) result[key] = val;
  }

  return result;
}

/** All key names found in .env.test (values are NOT exported). */
const _envFileEntries     = parseEnvFile(ENV_FILE);
const requiredSecretNames = Object.keys(_envFileEntries);

// ---------------------------------------------------------------------------
// 2. AWS Secrets Manager client (lazy-initialised so the module can be
//    imported without AWS credentials during unit tests).
// ---------------------------------------------------------------------------

let _smClient = null;

