/**
 * secrets.js
 *
 * Centralised secret-loading module.
 *
 * Resolution order
 * ────────────────
 * 1. AWS Secrets Manager  – always attempted first when the runtime environment
 *    has AWS credentials available (i.e. production / staging).
 * 2. .env.test fallback   – used automatically when Secrets Manager is
 *    unreachable or when NODE_ENV is "development" / "test".  The file is
 *    loaded with dotenv so no secret values are ever hard-coded here.
 *
 * Required secret names are derived exclusively from the keys present in
 * .env.test, so adding or removing a variable there keeps everything in sync.
 *
 * Usage
 * ─────
 *   const { getSecret, loadAll } = require('./secrets');
 *
 *   // Fetch a single secret (async)
 *   const dbUrl = await getSecret('DATABASE_URL');
 *
 *   // Pre-load all secrets into process.env at startup (async)
 *   await loadAll();
 */

'use strict';

const path = require('path');
const fs   = require('fs');

// ── dotenv ────────────────────────────────────────────────────────────────────
// Loaded once at module initialisation.  Values land in process.env and act as
// the local fallback; they are never read back out into a JS object here.
const dotenv = require('dotenv');
const ENV_FILE = path.resolve(__dirname, '.env.test');
dotenv.config({ path: ENV_FILE });

// ── AWS SDK ───────────────────────────────────────────────────────────────────
const {
  SecretsManagerClient,
  GetSecretValueCommand,
  ResourceNotFoundException,
} = require('@aws-sdk/client-secrets-manager');

// ── Configuration ─────────────────────────────────────────────────────────────
const IS_DEV =
  process.env.NODE_ENV === 'development' || process.env.NODE_ENV === 'test';

// AWS region is read from the environment so it is never hard-coded.
const AWS_REGION = process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION || 'us-east-1';

// Optional prefix that scopes every secret in Secrets Manager,
// e.g.  "myapp/production/"  →  "myapp/production/DATABASE_URL"
// Set via APP_SECRETS_PREFIX env var; defaults to empty string.
const SECRET_PREFIX = process.env.APP_SECRETS_PREFIX || '';

// ── Derive required secret names from .env.test ───────────────────────────────
/**
 * Parse .env.test with dotenv's own parser so we get the canonical key list
 * without importing the values into this module's scope.
 *
 * @returns {string[]} Array of environment-variable names found in .env.test.
 */
function requiredSecretNames() {
  if (!fs.existsSync(ENV_FILE)) {
    console.warn(`[secrets] ${ENV_FILE} not found – no required names loaded`);
    return [];
  }
  const parsed = dotenv.parse(fs.readFileSync(ENV_FILE));
  // Return only the keys, never the values.
  return Object.keys(parsed);
}

const REQUIRED_NAMES = requiredSecretNames();

// ── AWS Secrets Manager client (lazy singleton) ───────────────────────────────
let _smClient = null;

function getSmClient() {
  if (!_smClient) {
    _smClient = new SecretsManagerClient({ region: AWS_REGION });
  }
  return _smClient;
}

// ── In-process cache ──────────────────────────────────────────────────────────
// Secrets fetched from AWS are cached for the lifetime of the process so we
// avoid hammering the API on every request.
const _cache = new Map();

// ── Core fetch logic ──────────────────────────────────────────────────────────
/**
 * Attempt to retrieve a secret from AWS Secrets Manager.
 *
 * @param {string} secretId  Full secret name / ARN as stored in Secrets Manager.
 * @returns {Promise<string>} The plaintext secret value.
 * @throws  When the secret does not exist or AWS returns an error.
 */
async function fetchFromSecretsManager(secretId) {
  const client = getSmClient();
  const command = new GetSecretValueCommand({ SecretId: secretId });
  const response = await client.send(command);

  if (response.SecretString !== undefined) {
    return response.SecretString;
  }

  // Binary secrets are Base64-encoded in SecretBinary.
  if (response.SecretBinary !== undefined) {
    return Buffer.from(response.SecretBinary, 'base64').toString('utf8');
  }

  throw new Error(`[secrets] Secret "${secretId}" returned no value from Secrets Manager`);
}

// ── Public API ────────────────────────────────────────────────────────────────
/**
 * Retrieve a secret by name.
 *
 * Resolution order:
 *   1. In-process cache (populated on previous successful AWS fetches).
 *   2. AWS Secrets Manager  (skipped in development/test when AWS creds absent).
 *   3. process.env fallback (populated from .env.test by dotenv at startup).
 *
 * @param {string} name  The secret's environment-variable name, e.g. "DATABASE_URL".
 * @returns {Promise<string>} The secret value.
 * @throws  {Error} When the secret cannot be resolved from any source.
 */
async function getSecret(name) {
  // 1. Cache hit.
  if (_cache.has(name)) {
    return _cache.get(name);
  }

  // 2. AWS Secrets Manager (skipped in dev/test if no AWS creds configured).
  if (!IS_DEV || (process.env.AWS_ACCESS_KEY_ID && process.env.AWS_PROFILE)) {
    const secretId = `${SECRET_PREFIX}${name}`;
    try {
      const value = await fetchFromSecretsManager(secretId);
      _cache.set(name, value);
      return value;
    } catch (err) {
      if (err instanceof ResourceNotFoundException) {
        console.warn(
          `[secrets] "${secretId}" not found in Secrets Manager – falling back to .env.test`
        );
      } else if (IS_DEV) {
        // In dev mode, any AWS error (e.g. no credentials) is a soft warning.
        console.warn(
          `[secrets] Secrets Manager unavailable (${err.name}) – falling back to .env.test`
        );
      } else {
        // In production, a non-404 AWS error is fatal.
        throw new Error(
          `[secrets] Failed to fetch "${secretId}" from Secrets Manager: ${err.message}`
        );
      }
    }
  }

  // 3. process.env fallback (dotenv populated this at module load time).
  if (process.env[name] !== undefined) {
    return process.env[name];
  }

  throw new Error(
    `[secrets] "${name}" could not be resolved from Secrets Manager or .env.test`
  );
}

/**
 * Pre-load every secret listed in .env.test into the cache and process.env.
 *
 * Call this once at application startup (await loadAll()) so that all secrets
 * are available synchronously via process.env for libraries that read it
 * directly (e.g. database drivers).
 *
 * @returns {Promise<void>}
 */
async function loadAll() {
  const errors = [];

  await Promise.all(
    REQUIRED_NAMES.map(async (name) => {
      try {
        const value = await getSecret(name);
        // Write resolved value back to process.env for compatibility with
        // third-party libraries that read environment variables directly.
        process.env[name] = value;
      } catch (err) {
        errors.push(err.message);
      }
    })
  );

  if (errors.length > 0) {
    throw new Error(
      `[secrets] loadAll() failed to resolve the following secrets:\n  • ${errors.join('\n  • ')}`
    );
  }

  console.log(`[secrets] Loaded ${REQUIRED_NAMES.length} secret(s) successfully.`);
}

// ── Exports ───────────────────────────────────────────────────────────────────
module.exports = {
  /** Async: fetch a single secret by name. */
  getSecret,

  /** Async: pre-load all secrets from .env.test into cache + process.env. */
  loadAll,

  /**
   * The list of secret names derived from .env.test keys (no values).
   * Exposed for introspection / health-checks only.
   */
  REQUIRED_NAMES,
};

