  //   const ai = new Anthropic({ apiKey: anthropicKey });
  //
  //   etc.
  //
  // For now, just confirm the secrets resolved without printing their values:
  console.log('[app] Services configured:', [
    dbUrl        ? 'database'  : null,
    stripeKey    ? 'stripe'    : null,
