{
  "name": "p15-test-dedl3s",
  "version": "1.0.0",
  "description": "Express app with AWS Secrets Manager integration",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "start:dev": "NODE_ENV=development node app.js",
    "test": "node --test"
  },
  "keywords": [],
  "author": "",
  "license": "ISC",
  "dependencies": {
    "@aws-sdk/client-secrets-manager": "^3.0.0",
    "dotenv": "^16.0.0",
    "express": "^4.18.0"
  }
}

/**
 * secrets.js
 *
 * Centralised secret-loading module.
 *
 * Strategy
 * --------
 * Production  (NODE_ENV !== 'development'):
 *   Every call to getSecret(name) fetches the secret value from AWS Secrets
 *   Manager.  The secret is expected to be stored as a JSON object whose
 *   top-level keys match the names listed in .env.test (e.g. DATABASE_URL,
 *   STRIPE_SECRET_KEY …).  A per-process in-memory cache avoids redundant
 *   network round-trips within a single Lambda invocation / server process.
 *
 * Development (NODE_ENV === 'development'):
 *   .env.test is loaded via dotenv and getSecret(name) resolves from
 *   process.env.  No AWS credentials are required locally.
 *
 * Required secret names
 * ----------------------
 * The authoritative list of required secret names is derived at start-up by
 * parsing .env.test for *key names only* — values in that file are never read
 * or used by this module.
 *
 * AWS configuration
 * -----------------
 * The Secrets Manager secret ARN / name is supplied through the environment
 * variable SECRET_ARN (required in production).  AWS credentials are picked
 * up from the standard SDK credential chain (IAM role, environment variables,
 * ~/.aws/credentials) — they must NOT be stored in .env.test or this file.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// 1.  Parse .env.test for KEY NAMES ONLY
// ---------------------------------------------------------------------------

const ENV_FILE = path.resolve(__dirname, '.env.test');

/**
 * Returns the list of secret names declared in .env.test.
 * Only the left-hand side of each KEY=VALUE line is collected;
 * the values themselves are intentionally discarded here.
 *
 * @returns {string[]}
 */
function loadRequiredSecretNames() {
  if (!fs.existsSync(ENV_FILE)) {
    console.warn(`[secrets] ${ENV_FILE} not found — no required names loaded`);
    return [];
  }

  const lines = fs.readFileSync(ENV_FILE, 'utf8').split('\n');
  const names = [];

  for (const raw of lines) {
    const line = raw.trim();
    // Skip blank lines and comments
    if (!line || line.startsWith('#')) continue;

    const eqIndex = line.indexOf('=');
    if (eqIndex === -1) continue;

    const key = line.slice(0, eqIndex).trim();
    if (key) names.push(key);
  }

  return names;
}

/** Immutable list of secret names this application expects. */
const REQUIRED_SECRET_NAMES = loadRequiredSecretNames();

// ---------------------------------------------------------------------------
// 2.  Development fallback — load values into process.env via dotenv
// ---------------------------------------------------------------------------

const IS_DEVELOPMENT = process.env.NODE_ENV === 'development';

if (IS_DEVELOPMENT) {
  // dotenv.config() only sets a key when it is not already present in
  // process.env, so real environment variables always win.
  const { config } = require('dotenv');
  const result = config({ path: ENV_FILE });
  if (result.error) {
    console.warn(`[secrets] dotenv could not load ${ENV_FILE}:`, result.error.message);
  } else {
    console.log('[secrets] Development mode — secrets loaded from .env.test');
  }
}

// ---------------------------------------------------------------------------
// 3.  AWS Secrets Manager client (lazy-initialised, production only)
// ---------------------------------------------------------------------------

let _smClient = null;

function getSecretsManagerClient() {
  if (_smClient) return _smClient;

  const { SecretsManagerClient } = require('@aws-sdk/client-secrets-manager');

  // Region is resolved from the standard SDK chain
  // (AWS_REGION env var, ~/.aws/config, EC2 metadata, …).
  // Do NOT hard-code a region here.
  _smClient = new SecretsManagerClient({});
  return _smClient;
}

// ---------------------------------------------------------------------------
// 4.  In-memory cache (keyed by secret name, per-process lifetime)
// ---------------------------------------------------------------------------

/** @type {Map<string, string>} */
const _cache = new Map();

// ---------------------------------------------------------------------------
// 5.  Core: fetchFromSecretsManager
// ---------------------------------------------------------------------------

/**
 * Fetches a single secret value from AWS Secrets Manager.
 *
 * The secret identified by SECRET_ARN is expected to be a JSON object whose
 * keys are the application secret names (e.g. DATABASE_URL).  The entire
 * object is fetched once, then individual values are served from the cache.
 *
 * @param {string} name  Secret name (e.g. 'DATABASE_URL')
 * @returns {Promise<string>}
 */
async function fetchFromSecretsManager(name) {
  // Return cached value if available
  if (_cache.has(name)) return _cache.get(name);

  const secretArn = process.env.SECRET_ARN;
  if (!secretArn) {
    throw new Error(
      '[secrets] SECRET_ARN environment variable is not set. ' +
      'Provide the ARN or name of the Secrets Manager secret.'
    );
  }

  const { GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
  const client = getSecretsManagerClient();

  let response;
  try {
    response = await client.send(new GetSecretValueCommand({ SecretId: secretArn }));
  } catch (err) {
    throw new Error(`[secrets] Failed to retrieve secret "${secretArn}" from Secrets Manager: ${err.message}`);
  }

  // Secrets Manager returns either SecretString (JSON text) or SecretBinary.
  if (!response.SecretString) {
    throw new Error(
      `[secrets] Secret "${secretArn}" does not contain a SecretString. ` +
      'Ensure the secret is stored as a JSON key/value object.'
    );
  }

  let parsed;
  try {
    parsed = JSON.parse(response.SecretString);
  } catch {
    throw new Error(
      `[secrets] SecretString for "${secretArn}" is not valid JSON. ` +
      'Store the secret as a JSON object with keys matching your secret names.'
    );
  }

  if (typeof parsed !== 'object' || Array.isArray(parsed) || parsed === null) {
    throw new Error(
      `[secrets] SecretString for "${secretArn}" must be a JSON object, not a scalar or array.`
    );
  }

  // Populate cache with every key from the fetched secret so we only need
  // one API call per process regardless of how many secrets are requested.
  for (const [k, v] of Object.entries(parsed)) {
    _cache.set(k, String(v));
  }

  if (!_cache.has(name)) {
    throw new Error(
      `[secrets] Key "${name}" not found in secret "${secretArn}". ` +
      `Available keys: ${Object.keys(parsed).join(', ')}`
    );
  }

  return _cache.get(name);
}

// ---------------------------------------------------------------------------
// 6.  Public API
// ---------------------------------------------------------------------------

/**
 * Retrieves the value of a named secret.
 *
 * - Production: fetches from AWS Secrets Manager (cached after first call).
 * - Development: reads from process.env populated by .env.test.
 *
 * @param {string} name  The secret name (must match a key in .env.test /
 *                       the Secrets Manager JSON object).
 * @returns {Promise<string>}
 * @throws  If the secret is not found or cannot be retrieved.
 */
async function getSecret(name) {
  if (!REQUIRED_SECRET_NAMES.includes(name)) {
    // Warn but do not hard-block — allows caller to request ad-hoc secrets
    console.warn(
      `[secrets] "${name}" is not in the required secrets list derived from .env.test. ` +
      'Add it to .env.test (key only, no real value) if it is a new required secret.'
    );
  }

  if (IS_DEVELOPMENT) {
    const value = process.env[name];
    if (value === undefined) {
      throw new Error(
        `[secrets] "${name}" not found in process.env. ` +
        `Ensure it is defined in ${ENV_FILE}.`
      );
    }
    return value;
  }

  return fetchFromSecretsManager(name);
}

/**
 * Pre-warms the secret cache by fetching all required secrets in one
 * Secrets Manager API call.  Call this once at application start-up so that
 * individual getSecret() calls never block a request handler.
 *
 * No-op in development (values are already in process.env).
 *
 * @returns {Promise<void>}
 */
async function preloadSecrets() {
  if (IS_DEVELOPMENT) return;

  // A single call to fetchFromSecretsManager for any required name will
  // populate the cache for ALL keys returned by the secret, so we only need
  // one API round-trip.
  if (REQUIRED_SECRET_NAMES.length === 0) {
    console.warn('[secrets] preloadSecrets() called but REQUIRED_SECRET_NAMES is empty.');
    return;
  }

  await fetchFromSecretsManager(REQUIRED_SECRET_NAMES[0]);
  console.log(`[secrets] Pre-loaded ${_cache.size} secret(s) from Secrets Manager.`);
}

module.exports = {
  getSecret,
  preloadSecrets,
  REQUIRED_SECRET_NAMES,
};

'use strict';

/**
 * app.js
 *
 * All secret values are retrieved through secrets.js — never read directly
 * from process.env or hard-coded here.
 */

const express = require('express');
const { getSecret, preloadSecrets, REQUIRED_SECRET_NAMES } = require('./secrets');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Start-up: pre-load secrets before accepting traffic
// ---------------------------------------------------------------------------

/**
 * Initialise the application:
 *  1. Pre-warm the Secrets Manager cache (one API call, all secrets cached).
 *  2. Retrieve individual secret values needed for service connections.
 *  3. Start listening.
 *
 * Startup is intentionally async so that the server never opens its port
 * before secrets are available.
 */
async function start() {
  // One round-trip to Secrets Manager (or no-op in development).
  await preloadSecrets();

  // -------------------------------------------------------------------------
  // Retrieve the secrets this application needs.
  // Add or remove names here as the application evolves; the names must also
  // exist as keys in .env.test (development) / the Secrets Manager secret
  // (production).
  // -------------------------------------------------------------------------
  const [
    databaseUrl,
    anthropicApiKey,
    stripeSecretKey,
    logfireToken,
  ] = await Promise.all([
    getSecret('DATABASE_URL'),
    getSecret('ANTHROPIC_API_KEY'),
    getSecret('STRIPE_SECRET_KEY'),
    getSecret('LOGFIRE_TOKEN'),
  ]);

  // Pass retrieved values to the sub-systems that need them.
  // Shown here as illustrative log lines — a real app would pass them to
  // database clients, SDK constructors, etc.
  console.log('[app] DATABASE_URL  resolved:', redactSecret(databaseUrl));
  console.log('[app] ANTHROPIC_KEY resolved:', redactSecret(anthropicApiKey));
  console.log('[app] STRIPE_KEY    resolved:', redactSecret(stripeSecretKey));
  console.log('[app] LOGFIRE_TOKEN resolved:', redactSecret(logfireToken));

