 * Development (NODE_ENV === 'development'):
 *   .env.test is loaded via dotenv and getSecret(name) resolves from
 *   process.env.  No AWS credentials are required locally.
 *
 * Required secret names
 * ----------------------
 * The authoritative list of required secret names is derived at start-up by
 * parsing .env.test for *key names only* — values in that file are never read
 * or used by this module.
 *
 * AWS configuration
 * -----------------
 * The Secrets Manager secret ARN / name is supplied through the environment
 * variable SECRET_ARN (required in production).  AWS credentials are picked
 * up from the standard SDK credential chain (IAM role, environment variables,
 * ~/.aws/credentials) — they must NOT be stored in .env.test or this file.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// 1.  Parse .env.test for KEY NAMES ONLY
// ---------------------------------------------------------------------------

const ENV_FILE = path.resolve(__dirname, '.env.test');

/**
 * Returns the list of secret names declared in .env.test.
 * Only the left-hand side of each KEY=VALUE line is collected;
 * the values themselves are intentionally discarded here.
 *
 * @returns {string[]}
 */
function loadRequiredSecretNames() {
  if (!fs.existsSync(ENV_FILE)) {
    console.warn(`[secrets] ${ENV_FILE} not found — no required names loaded`);
    return [];
  }

  const lines = fs.readFileSync(ENV_FILE, 'utf8').split('\n');
  const names = [];

  for (const raw of lines) {
    const line = raw.trim();
    // Skip blank lines and comments
    if (!line || line.startsWith('#')) continue;

    const eqIndex = line.indexOf('=');
    if (eqIndex === -1) continue;

    const key = line.slice(0, eqIndex).trim();
    if (key) names.push(key);
  }

  return names;
}

/** Immutable list of secret names this application expects. */
const REQUIRED_SECRET_NAMES = loadRequiredSecretNames();

// ---------------------------------------------------------------------------
// 2.  Development fallback — load values into process.env via dotenv
// ---------------------------------------------------------------------------

const IS_DEVELOPMENT = process.env.NODE_ENV === 'development';

if (IS_DEVELOPMENT) {
  // dotenv.config() only sets a key when it is not already present in
  // process.env, so real environment variables always win.
  const { config } = require('dotenv');
  const result = config({ path: ENV_FILE });
  if (result.error) {
    console.warn(`[secrets] dotenv could not load ${ENV_FILE}:`, result.error.message);
  } else {
    console.log('[secrets] Development mode — secrets loaded from .env.test');
  }
}

// ---------------------------------------------------------------------------
// 3.  AWS Secrets Manager client (lazy-initialised, production only)
// ---------------------------------------------------------------------------

let _smClient = null;

function getSecretsManagerClient() {
  if (_smClient) return _smClient;

  const { SecretsManagerClient } = require('@aws-sdk/client-secrets-manager');

  // Region is resolved from the standard SDK chain
  // (AWS_REGION env var, ~/.aws/config, EC2 metadata, …).
  // Do NOT hard-code a region here.
  _smClient = new SecretsManagerClient({});
  return _smClient;
}

// ---------------------------------------------------------------------------
// 4.  In-memory cache (keyed by secret name, per-process lifetime)
// ---------------------------------------------------------------------------

/** @type {Map<string, string>} */
const _cache = new Map();

// ---------------------------------------------------------------------------
// 5.  Core: fetchFromSecretsManager
// ---------------------------------------------------------------------------

/**
 * Fetches a single secret value from AWS Secrets Manager.
 *
 * The secret identified by SECRET_ARN is expected to be a JSON object whose
 * keys are the application secret names (e.g. DATABASE_URL).  The entire
 * object is fetched once, then individual values are served from the cache.
 *
 * @param {string} name  Secret name (e.g. 'DATABASE_URL')
 * @returns {Promise<string>}
 */
async function fetchFromSecretsManager(name) {
  // Return cached value if available
  if (_cache.has(name)) return _cache.get(name);

  const secretArn = process.env.SECRET_ARN;
  if (!secretArn) {
    throw new Error(
      '[secrets] SECRET_ARN environment variable is not set. ' +
      'Provide the ARN or name of the Secrets Manager secret.'
    );
  }

  const { GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
  const client = getSecretsManagerClient();

  let response;
  try {
    response = await client.send(new GetSecretValueCommand({ SecretId: secretArn }));
  } catch (err) {
    throw new Error(`[secrets] Failed to retrieve secret "${secretArn}" from Secrets Manager: ${err.message}`);
  }

  // Secrets Manager returns either SecretString (JSON text) or SecretBinary.
  if (!response.SecretString) {
    throw new Error(
      `[secrets] Secret "${secretArn}" does not contain a SecretString. ` +
      'Ensure the secret is stored as a JSON key/value object.'
    );
  }

  let parsed;
  try {
    parsed = JSON.parse(response.SecretString);
  } catch {
    throw new Error(
      `[secrets] SecretString for "${secretArn}" is not valid JSON. ` +
      'Store the secret as a JSON object with keys matching your secret names.'
    );
  }

