/**
 * secrets.js
 *
 * Centralised secret resolution with two-tier lookup:
 *
 *   1. PRIMARY  – AWS Secrets Manager (always attempted in production)
 *   2. FALLBACK – .env.test values loaded by dotenv  (used in development /
 *                 when NODE_ENV !== 'production', or when Secrets Manager is
 *                 unreachable and a local value exists)
 *
 * The list of *required* secret names is derived exclusively from the keys
 * that are present in .env.test, so no secret names or values are hardcoded
 * here.
 *
 * Usage
 * -----
 *   const { getSecret, loadAllSecrets } = require('./secrets');
 *
 *   // Single lookup (lazy, cached after first call)
 *   const dbUrl = await getSecret('DATABASE_URL');
 *
 *   // Eager pre-flight: resolve all required secrets at startup and surface
 *   // missing ones as a single, actionable error instead of failing later.
 *   await loadAllSecrets();
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// 1. Parse .env.test to discover required secret names (keys only).
//    dotenv.config() is also called so the values are available as a
//    last-resort fallback in development – we never read them out of this
//    file for production use.
// ---------------------------------------------------------------------------
const dotenv   = require('dotenv');
const ENV_FILE = path.resolve(__dirname, '.env.test');

// Populate process.env from the file so the fallback path works automatically.
dotenv.config({ path: ENV_FILE });

/**
 * Parse an env file and return an array of the declared key names.
 * Lines starting with # (comments) and blank lines are ignored.
 * No values are returned – only the names.
 *
 * @param {string} filePath  Absolute path to the .env file.
 * @returns {string[]}       Ordered, de-duplicated list of key names.
 */
function parseEnvKeys(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`Secret definition file not found: ${filePath}`);
  }

  const lines = fs.readFileSync(filePath, 'utf8').split(/\r?\n/);
  const keys  = [];

  for (const raw of lines) {
    const line = raw.trim();
    // Skip blank lines and comments.
    if (!line || line.startsWith('#')) continue;

    // Accept   KEY=...   or   export KEY=...
    const match = line.match(/^(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=/);
    if (match) {
      const key = match[1];
      if (!keys.includes(key)) keys.push(key);
    }
  }

  return keys;
}

/** The canonical list of secret names this application requires. */
const REQUIRED_SECRET_NAMES = parseEnvKeys(ENV_FILE);

// ---------------------------------------------------------------------------
// 2. AWS Secrets Manager client (lazy-initialised so tests that never call
//    Secrets Manager don't need AWS credentials configured).
// ---------------------------------------------------------------------------
const {
  SecretsManagerClient,
  GetSecretValueCommand,
} = require('@aws-sdk/client-secrets-manager');

/** Singleton client – created on first use. */
let _smClient = null;

/**
 * Return (and cache) a SecretsManagerClient.
 * Region is read from the environment so nothing is hardcoded.
 *
 * @returns {SecretsManagerClient}
 */
function getSmClient() {
  if (!_smClient) {
    _smClient = new SecretsManagerClient({
      region: process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION || 'us-east-1',
    });
  }
  return _smClient;
}

// ---------------------------------------------------------------------------
// 3. In-process cache so each secret is fetched from Secrets Manager at most
//    once per process lifetime.
// ---------------------------------------------------------------------------

/** @type {Map<string, string>} */
const _cache = new Map();

// ---------------------------------------------------------------------------
// 4. Core resolution logic
// ---------------------------------------------------------------------------

const IS_PRODUCTION = process.env.NODE_ENV === 'production';

/**
 * Fetch the plaintext value of a single secret from AWS Secrets Manager.
 * Throws if the SDK call fails.
 *
 * @param {string} name  The secret name / ARN.
 * @returns {Promise<string>}
 */
async function fetchFromSecretsManager(name) {
  const command  = new GetSecretValueCommand({ SecretId: name });
  const response = await getSmClient().send(command);

  if (typeof response.SecretString === 'string') {
    // The secret may be stored as a raw string or as a JSON object.
    // If it is JSON, try to extract a property that matches the key name.
    try {
      const parsed = JSON.parse(response.SecretString);
      // If the JSON has a property with the same name as the secret, use it;
      // otherwise return the whole JSON string so callers can parse it
      // themselves.
      if (Object.prototype.hasOwnProperty.call(parsed, name)) {
        return String(parsed[name]);
      }
      // Single-value JSON blob – return raw string.
      return response.SecretString;
    } catch {
      // Not JSON – return as-is.
      return response.SecretString;
    }
  }

  // Binary secrets are returned as a Buffer.
  if (response.SecretBinary) {
    return Buffer.from(response.SecretBinary).toString('utf8');
  }

  throw new Error(`AWS Secrets Manager returned no value for secret: ${name}`);
